def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Three main clusters
    clusters = [
        {'cx': 20, 'cy': 50, 'wc': 20},
        {'cx': 60, 'cy': 50, 'wc': 60},
        {'cx': 100, 'cy': 50, 'wc': 100},
    ]

    # ---- Ensure all 3 primary plants exist ----
    for plant_cx, plant_cy in [(20, 50), (60, 50), (100, 50)]:
        plant_there = any(
            in_bounds(plant_cx + dx, plant_cy + dy) and bool(pm[plant_cy + dy, plant_cx + dx])
            for dy in range(-3, 4) for dx in range(-3, 4)
            if in_bounds(plant_cx + dx, plant_cy + dy)
        )
        if not plant_there:
            return (Tool.COALPOWER, plant_cx, plant_cy)

    # ---- Horizontal wire bridge between clusters (row 50) ----
    for x in range(22, 59):
        if in_bounds(x, 50) and bool(em[50, x]) and not bool(pm[50, x]):
            return (Tool.WIRE, x, 50)
    for x in range(62, 99):
        if in_bounds(x, 50) and bool(em[50, x]) and not bool(pm[50, x]):
            return (Tool.WIRE, x, 50)

    # ---- Extend vertical wire spines for each cluster ----
    pop_factor = min(25, obs.city_pop // 20)
    spine_extent = 14 + pop_factor

    for cl in clusters:
        wc = cl['wc']
        cy = cl['cy']
        spine_top = max(3, cy - spine_extent)
        spine_bot = min(WORLD_H - 4, cy + spine_extent)

        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            for dy in range(-2, 3):
                ny = cy + dy
                if in_bounds(wc, ny) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- Road columns flanking each cluster's wire spine ----
    for cl in clusters:
        wc = cl['wc']
        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        for road_off in [-1, 1]:
            rc = wc + road_off
            step_sub = obs.step % max(len(wire_rows), 1)
            for i in range(min(len(wire_rows), 3)):
                idx = (step_sub + i) % len(wire_rows)
                wr = wire_rows[idx]
                if in_bounds(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

    # ---- Additional nuclear plant when pop grows large ----
    if obs.city_pop > 800:
        nuke_positions = [(40, 30), (80, 30), (40, 70), (80, 70)]
        for npx, npy in nuke_positions:
            plant_there = any(
                in_bounds(npx + dx, npy + dy) and bool(pm[npy + dy, npx + dx])
                for dy in range(-4, 5) for dx in range(-4, 5)
                if in_bounds(npx + dx, npy + dy)
            )
            if not plant_there and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)
            if not plant_there:
                # Wire connection toward nearest cluster wire spine
                nearest_wc = min([cl['wc'] for cl in clusters], key=lambda wc: abs(wc - npx))
                # Connect horizontally
                for wx in range(min(npx, nearest_wc) + 1, max(npx, nearest_wc)):
                    if in_bounds(wx, npy) and bool(em[npy, wx]) and not bool(pm[npy, wx]):
                        return (Tool.WIRE, wx, npy)

    # ---- Fourth coal plant for mid-game boost ----
    if obs.city_pop > 400 and obs.city_pop <= 800:
        for extra_px, extra_py in [(40, 50), (80, 50)]:
            plant_there = any(
                in_bounds(extra_px + dx, extra_py + dy) and bool(pm[extra_py + dy, extra_px + dx])
                for dy in range(-4, 5) for dx in range(-4, 5)
                if in_bounds(extra_px + dx, extra_py + dy)
            )
            if not plant_there and bool(em[extra_py, extra_px]):
                return (Tool.COALPOWER, extra_px, extra_py)

    # ---- Proximity masks ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance to nearest cluster center
        min_dist = np.full(len(cxs_arr), 999999.0)
        for cl in clusters:
            d = np.abs(cxs_arr - cl['cx']) + np.abs(cys_arr - cl['cy'])
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 120:
                break

    # ---- Horizontal roads crossing wire spines every N rows ----
    for cl in clusters:
        wc = cl['wc']
        cy = cl['cy']
        pop_f = min(20, obs.city_pop // 20)
        spine_top = max(3, cy - min(14 + pop_f, 30))
        spine_bot = min(WORLD_H - 4, cy + min(14 + pop_f, 30))
        for wr in range(spine_top, spine_bot + 1, 6):
            x_lo = max(3, wc - 12)
            x_hi = min(WORLD_W - 4, wc + 12)
            for rx in range(x_lo, x_hi + 1):
                if in_bounds(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- Services at population thresholds ----
    if obs.city_pop > 150:
        for fsx, fsy in [(15, 42), (55, 42), (95, 42), (15, 58), (55, 58), (95, 58)]:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 400:
        for psx, psy in [(25, 42), (65, 42), (105, 42), (25, 58), (65, 58), (105, 58)]:
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 800:
        for stx, sty in [(40, 38), (80, 38), (40, 62), (80, 62)]:
            if in_bounds(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # ---- Extend roads near wire as fallback ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Expand wire as last fallback ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious closed-loop city builder
# Strategy: 5 power plants in a grid, extensive wire+road network,
# dense mixed zoning across large portions of the map

def init(obs, state):
    actions = []
    # 5 power plants: corners + center
    plants = [(20, 25), (100, 25), (20, 75), (100, 75), (60, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Connect center plant with wires to each corner plant
    # Horizontal wire at y=25 from x=22 to x=98
    for x in range(22, 100):
        actions.append((Tool.WIRE, x, 25))
    # Horizontal wire at y=75 from x=22 to x=98
    for x in range(22, 100):
        actions.append((Tool.WIRE, x, 75))
    # Vertical wire at x=20 from y=27 to y=73
    for y in range(27, 73):
        actions.append((Tool.WIRE, 20, y))
    # Vertical wire at x=100 from y=27 to y=73
    for y in range(27, 73):
        actions.append((Tool.WIRE, 100, y))
    # Seed roads near center plant
    for x in range(55, 66):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def inb(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Phase counter for deterministic variety
    step = obs.step
    pop = obs.city_pop

    # --- Ensure 5 plants exist (closed-loop check) ---
    plant_targets = [(20, 25), (100, 25), (20, 75), (100, 75), (60, 50)]
    for px, py in plant_targets:
        found = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = px+dx, py+dy
                if inb(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # --- Ensure wire backbone is connected ---
    # Check horizontal wires at y=25, y=50, y=75
    # Check vertical wires at x=20, x=60, x=100
    backbone = []
    # y=25 horizontal
    for x in range(22, 100):
        backbone.append((x, 25))
    # y=75 horizontal
    for x in range(22, 100):
        backbone.append((x, 75))
    # x=20 vertical
    for y in range(27, 73):
        backbone.append((20, y))
    # x=100 vertical
    for y in range(27, 73):
        backbone.append((100, y))
    # x=60 vertical connecting center
    for y in range(27, 73):
        backbone.append((60, y))
    # y=50 horizontal connecting center to sides
    for x in range(22, 100):
        backbone.append((x, 50))

    # Build missing wire - pick one per step based on step index
    missing_wire = [(x, y) for (x, y) in backbone
                    if inb(x, y) and em[y, x] and not pm[y, x] and not wm[y, x]]
    if missing_wire:
        idx = step % len(missing_wire)
        wx, wy = missing_wire[idx]
        return (Tool.WIRE, wx, wy)

    # --- Road network: grid of roads across the map ---
    # Roads every 6 rows and every 6 cols in the inhabited region
    road_rows = list(range(10, 90, 6))
    road_cols = list(range(10, 115, 6))

    # Check which road segments are missing
    missing_roads = []
    for ry in road_rows:
        for x in range(8, 112):
            if inb(x, ry) and em[ry, x] and not pm[ry, x]:
                missing_roads.append((x, ry))
    for rx in road_cols:
        for y in range(8, 92):
            if inb(rx, y) and em[y, rx] and not pm[y, rx]:
                missing_roads.append((rx, y))

    # Build missing roads - but only if near wire (power)
    # Compute wire neighborhood
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    powered_roads = [(x, y) for (x, y) in missing_roads if nbr_wire[y, x]]
    if powered_roads:
        idx = step % len(powered_roads)
        rx2, ry2 = powered_roads[idx]
        return (Tool.ROAD, rx2, ry2)

    # --- Zone placement: fill cells between roads with zones ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Road proximity mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not inb(nc2, nr2):
                    return False
                if not em[nr2, nc2] and not zone_tiles[nr2, nc2]:
                    return False
        return True

    # Candidate zone positions: empty, near road, near wire, not edge
    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Sort by distance to nearest plant to prefer powered areas
        plant_xs = np.array([p[0] for p in plant_targets])
        plant_ys = np.array([p[1] for p in plant_targets])
        min_dist = np.full(len(cxs), 1e9)
        for px2, py2 in plant_targets:
            d = np.abs(cxs - px2) + np.abs(cys - py2)
            min_dist = np.minimum(min_dist, d)

        order = np.argsort(min_dist)
        # Use step to cycle through candidates for variety
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 150)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Civic services based on population ---
    if pop > 300:
        fire_spots = [(30, 20), (90, 20), (30, 80), (90, 80),
                      (60, 35), (60, 65), (15, 50), (105, 50)]
        for sx, sy in fire_spots:
            if inb(sx, sy) and em[sy, sx]:
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = [(40, 15), (80, 15), (40, 85), (80, 85),
                        (15, 35), (105, 35), (15, 65), (105, 65)]
        for sx, sy in police_spots:
            if inb(sx, sy) and em[sy, sx]:
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        # Add nuclear plants for more power
        nuke_spots = [(60, 15), (60, 85), (40, 50), (80, 50)]
        for nx2, ny2 in nuke_spots:
            found = any(inb(nx2+dx, ny2+dy) and pm[ny2+dy, nx2+dx]
                       for dy in range(-4, 5) for dx in range(-4, 5)
                       if inb(nx2+dx, ny2+dy))
            if not found:
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        stadium_spots = [(35, 35), (85, 35), (35, 65), (85, 65)]
        for sx, sy in stadium_spots:
            if inb(sx, sy) and em[sy, sx]:
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        # Seaport and airport for big city
        if inb(10, 90) and em[90, 10]:
            return (Tool.SEAPORT, 10, 90)
        if inb(95, 10) and em[10, 95]:
            return (Tool.AIRPORT, 95, 10)

    # --- Fallback: extend wire from existing wire ---
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        k_start = (step * 13) % len(wire_xs)
        for i in range(min(len(wire_xs), 50)):
            k = (k_start + i * 7) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx2+dx2, wy2+dy2
                if inb(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    # --- Fallback: extend road from existing road ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k_start = (step * 11) % len(road_xs)
        for i in range(min(len(road_xs), 50)):
            k = (k_start + i * 9) % len(road_xs)
            rx3, ry3 = int(road_xs[k]), int(road_ys[k])
            for dx3, dy3 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx3, ny3 = rx3+dx3, ry3+dy3
                if inb(nx3, ny3) and em[ny3, nx3] and not pm[ny3, nx3] and nbr_wire[ny3, nx3]:
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place multiple power plants and seed infrastructure across the map."""
    actions = []
    # Three power plants spread horizontally at mid-height
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
        # Wire spines going up and down from each plant
        for dy in range(-5, 6):
            actions.append((Tool.WIRE, px, 50 + dy))
        # Roads flanking each wire spine
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Zone balance: target 40% RES, 30% COM, 30% IND
    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- NEIGHBORHOOD ANCHORS ----
    # 9 power plants in a 3x3 grid covering the whole map
    # Each has a wire column and road columns
    all_anchors = [
        # (plant_x, plant_y, wire_col, road_left, road_right)
        (20, 25,  21, 20, 22),
        (60, 25,  61, 60, 62),
        (100, 25, 101, 100, 102),
        (20, 50,  21, 20, 22),
        (60, 50,  61, 60, 62),
        (100, 50, 101, 100, 102),
        (20, 75,  21, 20, 22),
        (60, 75,  61, 60, 62),
        (100, 75, 101, 100, 102),
        # Extra anchors in between for denser coverage
        (40, 38,  41, 40, 42),
        (80, 38,  81, 80, 82),
        (40, 62,  41, 40, 42),
        (80, 62,  81, 80, 82),
        (40, 15,  41, 40, 42),
        (80, 15,  81, 80, 82),
        (40, 85,  41, 40, 42),
        (80, 85,  81, 80, 82),
    ]

    def num_active_anchors():
        if pop < 100:
            return 3
        elif pop < 300:
            return 5
        elif pop < 700:
            return 7
        elif pop < 1500:
            return 10
        elif pop < 3000:
            return 13
        else:
            return len(all_anchors)

    active_anchors = all_anchors[:num_active_anchors()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        # Check if there's a plant within 5 tiles
        has_plant = False
        for dx in range(-5, 6):
            for dy in range(-5, 6):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant at px, py or nearby
            for r in range(8):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE SPINE BUILDING ----
    pop_factor = min(35, pop // 10)
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 20 - pop_factor)
        spine_bot = min(WORLD_H - 3, py + 20 + pop_factor)

        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_col:
            # Seed wire near plant
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(wc, ny) and not bool(pm[ny, wc]):
                    if bool(em[ny, wc]) or bool(wm[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE CONNECTIONS between anchors in same row ----
    for i in range(len(active_anchors)):
        for j in range(i + 1, len(active_anchors)):
            px1, py1, wc1, _, _ = active_anchors[i]
            px2, py2, wc2, _, _ = active_anchors[j]
            if py1 == py2 and abs(wc1 - wc2) < 60:
                min_wc = min(wc1, wc2)
                max_wc = max(wc1, wc2)
                for cx in range(min_wc, max_wc + 1):
                    if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                        return (Tool.WIRE, cx, py1)

    # ---- VERTICAL WIRE CONNECTIONS between anchors in same column ----
    for i in range(len(active_anchors)):
        for j in range(i + 1, len(active_anchors)):
            px1, py1, wc1, _, _ = active_anchors[i]
            px2, py2, wc2, _, _ = active_anchors[j]
            if abs(wc1 - wc2) <= 3 and abs(py1 - py2) < 50:
                conn_x = wc1
                min_py = min(py1, py2)
                max_py = max(py1, py2)
                for cy in range(min_py, max_py + 1):
                    if ib(conn_x, cy) and bool(em[cy, conn_x]) and not bool(pm[cy, conn_x]):
                        return (Tool.WIRE, conn_x, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 3) % 3
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROAD CONNECTORS ----
    # Connect neighborhoods horizontally at multiple y-levels
    road_levels = []
    if pop > 50:
        road_levels.append(25)
        road_levels.append(50)
        road_levels.append(75)
    if pop > 400:
        road_levels.extend([15, 38, 62, 85])
    if pop > 1000:
        road_levels.extend([10, 30, 45, 55, 70, 90])

    for conn_y in road_levels:
        if not ib(5, conn_y):
            continue
        for cx in range(5, WORLD_W - 5):
            if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                # Only place if near wire
                near_wire = False
                for dy2 in range(-6, 7):
                    for dx2 in range(-6, 7):
                        nx2, ny2 = cx + dx2, conn_y + dy2
                        if ib(nx2, ny2) and (bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                            near_wire = True
                            break
                    if near_wire:
                        break
                if near_wire:
                    return (Tool.ROAD, cx, conn_y)

    # ---- BUILD PROXIMITY MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float) * 0.6
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 11) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 150:
        fire_spots = [
            (30, 25), (50, 25), (70, 25), (90, 25),
            (30, 50), (50, 50), (70, 50), (90, 50),
            (30, 75), (50, 75), (70, 75), (90, 75),
            (10, 38), (110, 38), (10, 62), (110, 62),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (35, 30), (65, 30), (95, 30),
            (35, 50), (65, 50), (95, 50),
            (35, 70), (65, 70), (95, 70),
            (15, 20), (105, 20), (15, 80), (105, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1200:
        stadium_spots = [
            (25, 15), (60, 15), (95, 15),
            (25, 85), (60, 85), (95, 85),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        # Upgrade to nuclear power for bigger coverage
        nuke_spots = [(30, 50), (90, 50), (60, 25), (60, 75)]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 4000:
        for asp in [(60, 10), (10, 50), (110, 50), (60, 90)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)
        for sp in [(15, 90), (105, 90), (60, 90)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 800:
        park_candidates = np.where(em & nbr_road)
        if len(park_candidates[0]) > 0:
            k = (step * 17) % len(park_candidates[0])
            py2 = int(park_candidates[0][k])
            px2 = int(park_candidates[1][k])
            if ib(px2, py2) and pop % 5 == 0:
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire laterally ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Combined ambitious policy: multiple clusters, dense zones, full map coverage

def init(obs, state):
    """Bootstrap: 3 coal plants + horizontal wire spine + flanking roads"""
    actions = []
