def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PROXIMITY MASKS (computed once) ----
    # Road neighbors within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power neighbors within 8 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Target anchors for plants: spread over whole map in a grid
    plant_anchors = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]
    # More plants as pop grows
    extra_anchors = [
        (40, 35), (80, 35),
        (40, 65), (80, 65),
        (10, 50), (115, 50),
    ]
    num_plants_needed = 3
    if pop > 200: num_plants_needed = 5
    if pop > 800: num_plants_needed = 7
    if pop > 2000: num_plants_needed = 9
    all_plant_anchors = (plant_anchors + extra_anchors)[:num_plants_needed]

    for (px, py) in all_plant_anchors:
        # Check if plant exists nearby
        has_plant = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Find nearby empty spot
            for r in range(1, 8):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE EXPANSION ----
    # For each plant, grow a wire spine vertically and horizontally
    # Find all plant tiles
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # Pick a plant based on step
        pidx = step % len(plant_xs)
        ppx, ppy = int(plant_xs[pidx]), int(plant_ys[pidx])
        # Try to extend wire from this plant outward
        # Prefer directions with no wire yet
        # Check for BFS-style: find nearest empty adjacent to existing wire/plant
        wpm = wm | pm
        wire_adj_empty = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            wire_adj_empty[r0:r1, c0:c1] |= wpm[sr0:sr1, sc0:sc1]
        # Candidates: empty cells adjacent to wire/plant, not already wire/plant
        wire_ext_cands = em & wire_adj_empty & ~pm
        # Filter: cells that have no wire neighbor on the far side (prefer extending frontiers)
        we_ys, we_xs = np.where(wire_ext_cands)
        if len(we_xs) > 0:
            # Score by distance to nearest anchor needing wire coverage
            # Simple: pick candidate closest to uncovered plant anchor
            best_score = -1e9
            best_x, best_y = -1, -1
            # Score = how much it extends coverage toward underserved areas
            # Use step-based cycling to vary direction
            anchor_targets = all_plant_anchors
            # Find anchors not yet well-wired
            step_pick = (step * 7) % max(len(we_xs), 1)
            # Try a batch of candidates
            n_try = min(60, len(we_xs))
            for i in range(n_try):
                k = (step_pick + i * 3) % len(we_xs)
                cx, cy = int(we_xs[k]), int(we_ys[k])
                # Score: distance from nearest plant (lower = better wire extension)
                # Also prefer cells not near existing wire (frontier)
                near_wire_count = int(np.sum(wm[max(0,cy-3):cy+4, max(0,cx-3):cx+4]))
                dist_to_nearest_plant = min(
                    abs(cx - px2) + abs(cy - py2) for (px2, py2) in anchor_targets
                )
                # Prefer candidates near plants but in open territory
                score = -dist_to_nearest_plant - near_wire_count * 2
                if score > best_score:
                    best_score = score
                    best_x, best_y = cx, cy
            if best_x >= 0:
                return (Tool.WIRE, best_x, best_y)

    # ---- PHASE 3: ROAD EXPANSION ----
    # Extend roads adjacent to existing roads, preferring areas near wire
    road_adj_empty = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
        sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
        r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
        c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
        road_adj_empty[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    road_ext_cands = em & road_adj_empty & nbr_wire & ~pm
    re_ys, re_xs = np.where(road_ext_cands)
    if len(re_xs) > 0:
        step_pick = (step * 11) % max(len(re_xs), 1)
        # Score: prefer cells that extend road toward uncovered areas
        best_score = -1e9
        best_x, best_y = -1, -1
        n_try = min(80, len(re_xs))
        for i in range(n_try):
            k = (step_pick + i * 5) % len(re_xs)
            cx, cy = int(re_xs[k]), int(re_ys[k])
            # Prefer roads near wire and not already near a road cluster
            near_road_count = int(np.sum(rm[max(0,cy-4):cy+5, max(0,cx-4):cx+5]))
            # Prefer spreading roads around
            score = -near_road_count
            if score > best_score:
                best_score = score
                best_x, best_y = cx, cy
        if best_x >= 0:
            return (Tool.ROAD, best_x, best_y)

    # ---- PHASE 4: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates away from existing zones (spread out)
        step_off = (step * 7) % max(len(cxs), 1)
        best_score = -1e9
        best_x, best_y = -1, -1
        n_try = min(120, len(cxs))
        for i in range(n_try):
            k = (step_off + i * 9) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if not zone_clear(zx, zy):
                continue
            # Score: prefer cells away from existing zone clusters but near road+wire
            near_zone = int(np.sum(zone_tiles[max(0,zy-5):zy+6, max(0,zx-5):zx+6]))
            score = -near_zone
            if score > best_score:
                best_score = score
                best_x, best_y = zx, zy
        if best_x >= 0:
            return (pick_tool(), best_x, best_y)

    # ---- PHASE 5: CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [
            (25, 15), (55, 15), (85, 15), (110, 15),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (25, 75), (55, 75), (85, 75), (110, 75),
            (35, 30), (65, 30), (95, 30),
            (35, 60), (65, 60), (95, 60),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (20, 20), (50, 20), (80, 20), (110, 20),
            (20, 40), (50, 40), (80, 40), (110, 40),
            (20, 60), (50, 60), (80, 60), (110, 60),
            (20, 80), (50, 80), (80, 80), (110, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (30, 10), (70, 10), (110, 10),
            (30, 90), (70, 90), (110, 90),
            (5, 25), (5, 50), (5, 75),
            (115, 25), (115, 50), (115, 75),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuclear_spots = [
            (40, 8), (80, 8), (40, 92), (80, 92),
            (5, 40), (5, 60), (115, 40), (115, 60),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        for asp in [(60, 6), (6, 50), (114, 50), (60, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)
        for sp in [(10, 94), (110, 94), (10, 6), (110, 6)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    if pop > 4000:
        park_ys, park_xs = np.where(em & nbr_road)
        if len(park_xs) > 0:
            pk = (step * 17) % len(park_xs)
            return (Tool.PARK, int(park_xs[pk]), int(park_ys[pk]))

    # ---- FALLBACK: place wire from any plant ----
    plant_ys2, plant_xs2 = np.where(pm)
    if len(plant_xs2) > 0:
        for pidx2 in range(len(plant_xs2)):
            ppx2, ppy2 = int(plant_xs2[pidx2]), int(plant_ys2[pidx2])
            for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = ppx2 + dx, ppy2 + dy
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- ABSOLUTE FALLBACK: place a coal plant ----
    em_ys, em_xs = np.where(em)
    if len(em_xs) > 0:
        k = step % len(em_xs)
        return (Tool.COALPOWER, int(em_xs[k]), int(em_ys[k]))

    return None

