        return True

    # ---- ACTIVE NEIGHBORHOODS based on population ----
    # Dense grid of wire columns across the map
    all_wire_cols = [10, 20, 35, 50, 60, 70, 85, 95, 110]
    # Multiple plant rows per column
    plant_rows = [20, 50, 78]

