            return 4
        elif pop < 600:
            return 5
        elif pop < 1000:
            return 6
        elif pop < 2000:
            return 7
        elif pop < 4000:
            return 8
        else:
            return 9

    n_cols = num_active_cols()
    active_cols = all_wire_cols[:n_cols]

    # ---- PHASE 1: ENSURE POWER PLANTS in active columns ----
    plants_needed_per_col = max(1, n_cols // 4)
    for wc in active_cols:
        for pr in plant_rows[:plants_needed_per_col]:
            has_plant = False
            for dx in range(-8, 9):
                for dy in range(-8, 9):
                    nx, ny = wc + dx, pr + dy
                    if ib(nx, ny) and bool(pm[ny, nx]):
                        has_plant = True
                        break
                if has_plant:
                    break
            if not has_plant:
                for r in range(0, 12):
                    placed = False
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if r > 0 and abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = wc + dx2, pr + dy2
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # ---- PHASE 2: EXTEND WIRE SPINES vertically from plants ----
    spine_half = min(45, 12 + pop // 15)
    for wc in active_cols:
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            # Seed wire near a plant in this column
            for pr in plant_rows:
                for dy2 in range(-6, 7):
                    ny = pr + dy2
                    if ib(wc, ny) and not bool(pm[ny, wc]):
                        if bool(em[ny, wc]) or bool(wm[ny, wc]):
                            return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            target_top = max(2, 50 - spine_half)
            target_bot = min(WORLD_H - 3, 50 + spine_half)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- PHASE 3: HORIZONTAL WIRE CONNECTIONS between neighboring columns ----
    for i in range(len(active_cols) - 1):
        c1 = active_cols[i]
        c2 = active_cols[i + 1]
        for conn_y in [18, 35, 50, 65, 82]:
            # Check if both ends have wire nearby
            has_left = any(bool(wm[conn_y, cx]) or bool(pm[conn_y, cx]) for cx in range(max(0, c1 - 2), min(WORLD_W, c1 + 3)))
            has_right = any(bool(wm[conn_y, cx]) or bool(pm[conn_y, cx]) for cx in range(max(0, c2 - 2), min(WORLD_W, c2 + 3)))
            if not (has_left or has_right):
                continue
            # Fill gaps in horizontal wire connection
            for cx in range(c1, c2 + 1):
                if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                    # Check neighbor connectivity
                    has_nbr = (bool(wm[conn_y, max(0, cx - 1)]) or bool(wm[conn_y, min(WORLD_W - 1, cx + 1)]) or
                                bool(pm[conn_y, max(0, cx - 1)]) or bool(pm[conn_y, min(WORLD_W - 1, cx + 1)]))
                    if has_nbr:
                        return (Tool.WIRE, cx, conn_y)

    # ---- PHASE 4: ROADS flanking wire spines ----
    road_half = min(45, 10 + pop // 20)
    for idx, wc in enumerate(active_cols):
        rl, rr = wc - 1, wc + 1
        if not ib(rl, 50) or not ib(rr, 50):
            continue
        wire_in_col = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not wire_in_col:
            continue
        target_top = max(2, 50 - road_half)
        target_bot = min(WORLD_H - 3, 50 + road_half)
        cycle = (step + idx * 3) % 3
        for wr in wire_in_col[cycle::3]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- PHASE 5: HORIZONTAL ROAD CONNECTIONS between columns ----
    if pop > 50:
        for conn_y in [17, 33, 49, 65, 81]:
            road_in_row = [c for c in range(WORLD_W) if ib(c, conn_y) and bool(rm[conn_y, c])]
            if not road_in_row:
                continue
            min_r = min(road_in_row)
            max_r = max(road_in_row)
            # Extend to cover all active columns
            for wc in sorted(active_cols):
                target = wc - 1
                if target < min_r:
                    for cx in range(target, min_r):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)
            for wc in sorted(active_cols, reverse=True):
                target = wc + 1
                if target > max_r:
                    for cx in range(max_r + 1, target + 1):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)

    # ---- PHASE 6: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for wc in active_cols:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - 50).astype(float) * 0.25
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 250:
                break

    # ---- PHASE 7: EXTEND ROADS from existing roads near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (30, 25), (60, 25), (90, 25), (15, 40), (45, 40), (75, 40), (105, 40),
            (15, 60), (45, 60), (75, 60), (105, 60), (30, 75), (60, 75), (90, 75),
            (20, 10), (50, 10), (80, 10), (110, 10), (20, 90), (50, 90), (80, 90), (110, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (12, 30), (35, 30), (58, 30), (82, 30), (105, 30),
            (12, 50), (35, 50), (58, 50), (82, 50), (105, 50),
            (12, 70), (35, 70), (58, 70), (82, 70), (105, 70),
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 85), (55, 85), (85, 85), (115, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (30, 10), (65, 10), (100, 10),
            (30, 90), (65, 90), (100, 90),
            (5, 30), (5, 70), (115, 30), (115, 70),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (30, 8), (75, 8), (110, 8),
            (30, 92), (75, 92), (110, 92),
            (5, 25), (5, 50), (5, 75),
            (115, 25), (115, 50), (115, 75),
        ]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3000:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 95)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 92), (115, 92), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys, zone_xs = np.where(zone_map)
        if len(zone_xs) > 0:
            for i in range(min(len(zone_xs), 30)):
                k = (step * 3 + i * 17) % len(zone_xs)
                zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (0, 3), (-3, 0), (0, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and bool(nbr_road[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- ABSOLUTE FALLBACK: place coal plant if no power ----
    if not np.any(pm):
        for y in range(10, 90, 5):
            for x in range(10, 110, 5):
                if bool(em[y, x]):
                    return (Tool.COALPOWER, x, y)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants in a row with wire spines and flanking roads."""
    actions = []
    # Three plants spread across the middle row
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px + 2, 50 + dy))
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px + 1, 50 + dy))
            actions.append((Tool.ROAD, px + 3, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- NEIGHBORHOOD ANCHORS ----
    # Each anchor: (plant_x, plant_y, wire_col, road_l, road_r)
    # Spread across the full 120x100 map in a 4x3 grid
    anchors = [
        # Row 1 (y=20)
        (13, 20, 15, 14, 16),
        (43, 20, 45, 44, 46),
        (73, 20, 75, 74, 76),
        (103, 20, 105, 104, 106),
        # Row 2 (y=50)
        (13, 50, 15, 14, 16),
        (43, 50, 45, 44, 46),
        (73, 50, 75, 74, 76),
        (103, 50, 105, 104, 106),
        # Row 3 (y=80)
        (13, 80, 15, 14, 16),
        (43, 80, 45, 44, 46),
        (73, 80, 75, 74, 76),
        (103, 80, 105, 104, 106),
    ]

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 350:  return 3
        if pop < 700:  return 4
        if pop < 1200: return 6
        if pop < 2000: return 8
        if pop < 3000: return 10
        return 12

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        has_plant = False
        for dx in range(-4, 5):
            for dy in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 10):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE BUILDING ----
    spine_half = min(18, 8 + pop // 30)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE between anchors at same row ----
    # Group anchors by y-level
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for conn_y in [yl]:
                for cx in range(wc1, wc2 + 1):
                    if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                        return (Tool.WIRE, cx, conn_y)

    # ---- VERTICAL WIRE between anchor rows ----
    if n_active >= 5:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1, py2 + 1):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at key y-levels ----
    if pop > 100:
        road_y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
        for ry in road_y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == ry],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            horiz_y = ry - 2  # road row above wire row
            if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                continue
            for cx in range(rl1, rr_last + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.5)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 150:
        fire_spots = [
            (28, 20), (58, 20), (88, 20), (118, 20),
            (28, 50), (58, 50), (88, 50), (118, 50),
            (28, 80), (58, 80), (88, 80), (118, 80),
            (8, 35), (8, 65), (108, 35), (108, 65),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (30, 35), (60, 35), (90, 35),
            (30, 65), (60, 65), (90, 65),
            (10, 20), (10, 50), (10, 80),
            (110, 20), (110, 50), (110, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1200:
        stadium_spots = [
            (35, 10), (75, 10), (115, 10),
            (35, 90), (75, 90), (115, 90),
            (5, 35), (5, 65), (115, 35), (115, 65),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        nuke_spots = [
            (30, 8), (70, 8), (110, 8),
            (30, 92), (70, 92), (110, 92),
            (5, 30), (5, 70), (115, 30), (115, 70),
        ]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 4000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 6000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 400:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 15)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
