def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Industry for jobs, commercial for services, residential to fill
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- NEIGHBORHOOD GRID ----
    # 5 columns x 4 rows = 20 neighborhoods, use all 120x100 map
    # Plant positions, wire columns, road offsets
    neighborhoods = []
    for col_i, px in enumerate([12, 32, 60, 88, 108]):
        for row_i, py in enumerate([15, 38, 62, 85]):
            neighborhoods.append((px, py))

    # How many neighborhoods to activate based on pop
    def num_active():
        if pop < 50:   return 1
        if pop < 200:  return 3
        if pop < 500:  return 6
        if pop < 1000: return 10
        if pop < 2000: return 15
        return len(neighborhoods)

    active_nh = neighborhoods[:num_active()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_nh:
        # Check if plant exists within 8 tiles
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant
            if ib(px, py):
                return (Tool.COALPOWER, px, py)

    # ---- WIRE SPINES: extend wire from each active plant vertically ----
    # Wire runs through plant column from py-15 to py+15
    for (px, py) in active_nh:
        spine_top = max(2, py - 15)
        spine_bot = min(WORLD_H - 3, py + 15)
        # Check for gaps in wire column
        col_has_wire = wm[:, px] | pm[:, px]
        for wy in range(spine_top, spine_bot + 1):
            if ib(px, wy) and not col_has_wire[wy] and not bool(pm[wy, px]):
                return (Tool.WIRE, px, wy)

    # ---- HORIZONTAL WIRE: connect all active neighborhoods in same row ----
    row_dict = {}
    for (px, py) in active_nh:
        row_dict.setdefault(py, []).append(px)
    for py, cols in row_dict.items():
        if len(cols) < 2:
            continue
        cols_s = sorted(cols)
        for i in range(len(cols_s) - 1):
            c1, c2 = cols_s[i], cols_s[i+1]
            for cx in range(c1, c2 + 1):
                if ib(cx, py) and bool(em[py, cx]) and not bool(pm[py, cx]):
                    return (Tool.WIRE, cx, py)

    # ---- VERTICAL WIRE: connect neighborhoods in same column ----
    col_dict = {}
    for (px, py) in active_nh:
        col_dict.setdefault(px, []).append(py)
    for px, rows in col_dict.items():
        if len(rows) < 2:
            continue
        rows_s = sorted(rows)
        for i in range(len(rows_s) - 1):
            r1, r2 = rows_s[i], rows_s[i+1]
            for ry in range(r1, r2 + 1):
                if ib(px, ry) and bool(em[ry, px]) and not bool(pm[ry, px]):
                    return (Tool.WIRE, px, ry)

    # ---- ROAD BUILDING: two vertical roads flanking each wire spine ----
    # Also horizontal roads at neighborhood rows
    for idx, (px, py) in enumerate(active_nh):
        spine_top = max(2, py - 15)
        spine_bot = min(WORLD_H - 3, py + 15)
        # Roads at px-1 and px+2 (leave px-0 for wire)
        for rx in [px - 2, px + 2]:
            if not ib(rx, py):
                continue
            col_has_road = rm[:, rx]
            for ry in range(spine_top, spine_bot + 1):
                if ib(rx, ry) and not col_has_road[ry] and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- HORIZONTAL ROADS at neighborhood rows ----
    for py in set(p[1] for p in active_nh):
        road_y_top = py - 2
        road_y_bot = py + 2
        for road_y in [road_y_top, road_y_bot]:
            if not ib(0, road_y):
                continue
            row_road = rm[road_y, :]
            for cx in range(5, WORLD_W - 5):
                if not row_road[cx] and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    # Only build if near wire
                    x0 = max(0, cx - 5); x1 = min(WORLD_W, cx + 6)
                    y0 = max(0, road_y - 5); y1 = min(WORLD_H, road_y + 6)
                    if np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1]):
                        return (Tool.ROAD, cx, road_y)

    # ---- BUILD PROXIMITY MASKS ----
    # Road proximity (within 2)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire proximity (within 5)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        """Check 3x3 area around center is empty or already zone."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize by distance to nearest active anchor
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_nh:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 100:
        fire_spots = [
            (25, 25), (55, 25), (85, 25), (110, 25),
            (25, 50), (55, 50), (85, 50), (110, 50),
            (25, 75), (55, 75), (85, 75), (110, 75),
            (10, 15), (10, 50), (10, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (30, 20), (65, 20), (95, 20),
            (30, 45), (65, 45), (95, 45),
            (30, 70), (65, 70), (95, 70),
            (15, 35), (15, 65), (105, 35), (105, 65),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (40, 10), (80, 10), (40, 90), (80, 90),
            (10, 30), (110, 30), (10, 70), (110, 70),
            (60, 45),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (35, 8), (75, 8), (35, 92), (75, 92),
            (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3500:
        for asp in [(60, 5), (8, 50), (112, 50)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(8, 90), (112, 90), (60, 95)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS for land value ----
    if pop > 800:
        park_spots = [
            (42, 28), (68, 28), (42, 72), (68, 72),
            (20, 50), (100, 50),
        ]
        for (px2, py2) in park_spots:
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

