def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    pwr = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.15:
            return Tool.INDUSTRIAL
        if c_r < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Ensure plants exist based on population ---
    # Grid of plants: 4 quadrants expanding outward
    plant_targets = [(30, 50), (90, 50)]
    if pop >= 0:
        plant_targets += [(60, 25), (60, 75)]
    if pop > 200:
        plant_targets += [(30, 25), (90, 25), (30, 75), (90, 75)]
    if pop > 600:
        plant_targets += [(10, 50), (110, 50), (60, 10), (60, 90)]
    if pop > 1200:
        plant_targets += [(10, 25), (110, 25), (10, 75), (110, 75)]
        plant_targets += [(45, 10), (75, 10), (45, 90), (75, 90)]
    if pop > 2000:
        plant_targets += [(20, 10), (100, 10), (20, 90), (100, 90)]
        plant_targets += [(5, 40), (115, 40), (5, 60), (115, 60)]
    if pop > 3000:
        plant_targets += [(40, 5), (80, 5), (40, 95), (80, 95)]
        plant_targets += [(5, 15), (115, 15), (5, 85), (115, 85)]

    for px, py in plant_targets:
        if not ib(px, py):
            continue
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # --- Phase 2: Wire network - connect plants together ---
    # Build horizontal wire corridors
    wire_rows = [10, 25, 50, 75, 90]
    if pop > 400:
        wire_rows += [37, 62]
    if pop > 1000:
        wire_rows += [18, 43, 57, 82]

    for wr in wire_rows:
        if not ib(0, wr):
            continue
        row_wire = wm[wr, :] | pm[wr, :]
        if not row_wire.any():
            continue
        # Extend leftward
        left = int(np.argmax(row_wire))
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Extend rightward
        right = WORLD_W - 1 - int(np.argmax(row_wire[::-1]))
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)

    # Vertical wire spines - connect horizontal rows
    wire_cols = [10, 30, 60, 90, 110]
    if pop > 400:
        wire_cols += [45, 75]
    if pop > 1000:
        wire_cols += [20, 52, 68, 100]

    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_wire = wm[:, wc] | pm[:, wc]
        if not col_wire.any():
            continue
        top = int(np.argmax(col_wire))
        bot = WORLD_H - 1 - int(np.argmax(col_wire[::-1]))
        # Target extent based on pop
        target_top = max(3, 5 - min(pop // 300, 4))
        target_bot = min(WORLD_H - 4, 95 + min(pop // 300, 4))
        if top > target_top:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < target_bot:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)

    # Fill wire gaps in wire rows
    for wr in wire_rows:
        row_wire = wm[wr, :] | pm[wr, :]
        if not row_wire.any():
            continue
        # Find gaps between wire segments
        left_end = -1
        for x in range(WORLD_W):
            if row_wire[x]:
                if left_end >= 0:
                    left_end = x
                else:
                    left_end = x
            elif left_end >= 0:
                # gap at x; check if right side has wire
                has_right = row_wire[x+1:].any() if x + 1 < WORLD_W else False
                if has_right and em[wr, x]:
                    return (Tool.WIRE, x, wr)
                left_end = -1

    # --- Phase 3: Road network ---
    road_rows = [9, 24, 45, 55, 74, 91]
    if pop > 300:
        road_rows += [36, 63]
    if pop > 800:
        road_rows += [17, 42, 58, 83]
    if pop > 1500:
        road_rows += [5, 95]

    road_cols = [9, 29, 59, 89, 111]
    if pop > 300:
        road_cols += [44, 74]
    if pop > 800:
        road_cols += [19, 51, 69, 99]
    if pop > 1500:
        road_cols += [4, 115]

    # Build horizontal roads
    for rr in road_rows:
        if not ib(0, rr):
            continue
        # Check if adjacent rows have wire
        has_wire_adj = False
        for dy in [-1, 0, 1]:
            nr = rr + dy
            if ib(0, nr) and (wm[nr, :] | pm[nr, :]).any():
                has_wire_adj = True
                break
        if not has_wire_adj:
            continue
        # Extend road
        for x in range(2, WORLD_W - 2):
            if em[rr, x] and not pm[rr, x] and not rm[rr, x]:
                # Check connectivity
                lc = ib(x-1, rr) and rm[rr, x-1]
                rc2 = ib(x+1, rr) and rm[rr, x+1]
                if lc or rc2:
                    return (Tool.ROAD, x, rr)
            # Seed if nothing yet
        row_road = rm[rr, :]
        if not row_road.any():
            # Plant a seed road near a wire col
            for wc in wire_cols:
                if ib(wc, rr) and em[rr, wc] and not pm[rr, wc]:
                    return (Tool.ROAD, wc, rr)

    # Build vertical roads
    for rc in road_cols:
        if not ib(rc, 0):
            continue
        has_wire_adj = False
        for dx in [-1, 0, 1]:
            nc = rc + dx
            if ib(nc, 0) and (wm[:, nc] | pm[:, nc]).any():
                has_wire_adj = True
                break
        if not has_wire_adj:
            continue
        for y in range(2, WORLD_H - 2):
            if em[y, rc] and not pm[y, rc] and not rm[y, rc]:
                uc = ib(rc, y-1) and rm[y-1, rc]
                dc = ib(rc, y+1) and rm[y+1, rc]
                if uc or dc:
                    return (Tool.ROAD, rc, y)
        col_road = rm[:, rc]
        if not col_road.any():
            for wr in wire_rows:
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # --- Phase 4: Zone placement ---
    # Proximity to roads (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Proximity to power (within 5 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone spots: empty, near road, near wire
    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score by distance to nearest plant (closer = better)
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in plant_targets:
            if ib(px, py):
                d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
                min_dist = np.minimum(min_dist, d)

        # Also cluster near existing zones
        if total_zones > 2:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            if len(zone_xs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                step2 = max(1, len(zone_xs2) // 60)
                for i in range(0, len(zone_xs2), step2):
                    d2 = np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])
                    zone_dist = np.minimum(zone_dist, d2)
                combined = min_dist * 0.5 + zone_dist * 0.5
            else:
                combined = min_dist
        else:
            combined = min_dist

        order = np.argsort(combined)
        # Vary starting offset to spread placements
        off = (step * 7 + pop) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # --- Phase 5: Civic services ---
    if pop > 50:
        fire_spots = [
            (28, 38), (32, 38), (88, 38), (92, 38),
            (28, 62), (32, 62), (88, 62), (92, 62),
            (58, 22), (62, 22), (58, 78), (62, 78),
            (10, 30), (110, 30), (10, 70), (110, 70),
            (45, 15), (75, 15), (45, 85), (75, 85),
            (20, 50), (100, 50),
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_spots = [
            (25, 36), (35, 36), (85, 36), (95, 36),
            (25, 64), (35, 64), (85, 64), (95, 64),
            (55, 18), (65, 18), (55, 82), (65, 82),
            (10, 50), (110, 50),
            (40, 8), (80, 8), (40, 92), (80, 92),
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_spots = [
            (50, 42), (70, 42), (50, 58), (70, 58),
            (38, 32), (82, 32), (38, 68), (82, 68),
            (60, 50), (25, 50), (95, 50),
            (40, 20), (80, 20), (40, 80), (80, 80),
        ]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        for stx, sty in [
            (42, 30), (78, 30), (42, 70), (78, 70),
            (20, 48), (100, 48), (60, 15), (60, 85),
            (15, 25), (105, 25), (15, 75), (105, 75),
        ]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        for apx, apy in [
            (55, 7), (55, 93), (8, 38), (112, 38), (8, 62), (112, 62),
        ]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        for spx, spy in [
            (7, 50), (113, 50), (60, 4), (60, 96),
            (25, 5), (95, 5), (25, 95), (95, 95),
        ]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend roads near wire ---
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        sk = (step * 11) % len(rxs)
        for offset in range(min(len(rxs), 100)):
            k = (sk + offset * 7) % len(rxs)
            rx2, ry2 = int(rxs[k]), int(rys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire from existing wire ---
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 60)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

