def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- DYNAMIC CONFIGURATION based on pop ----
    # Wire columns across map
    all_wire_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]

    def num_active_cols():
        if pop < 50:    return 3
        if pop < 200:   return 4
        if pop < 500:   return 5
        if pop < 1000:  return 6
        if pop < 2000:  return 7
        if pop < 4000:  return 8
        if pop < 7000:  return 9
        return 10

    n_cols = num_active_cols()
    col_indices = np.linspace(0, len(all_wire_cols) - 1, n_cols, dtype=int)
    active_cols = [all_wire_cols[i] for i in col_indices]

    # Plant rows
    all_plant_rows = [10, 25, 40, 55, 70, 85, 95]

    def num_plant_rows():
        if pop < 200:   return 2
        if pop < 800:   return 3
        if pop < 2000:  return 4
        if pop < 5000:  return 5
        if pop < 10000: return 6
        return 7

    n_prows = num_plant_rows()
    active_plant_rows = all_plant_rows[:n_prows]

    spine_half = min(47, 15 + pop // 20)

    # ---- ENSURE POWER PLANTS ----
    for wc in active_cols:
        for pr in active_plant_rows:
            has_plant = bool(np.any(pm[max(0, pr - 8):min(WORLD_H, pr + 9),
                                       max(0, wc - 8):min(WORLD_W, wc + 9)]))
            if not has_plant and ib(wc, pr):
                # Try to place near target
                for r in range(12):
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if r > 0 and abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = wc + dx2, pr + dy2
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE SPINES vertically ----
    for wc in active_cols:
        col_wires = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        target_top = max(2, 50 - spine_half)
        target_bot = min(WORLD_H - 3, 50 + spine_half)
        if not col_wires:
            # Seed near nearest plant
            for pr in active_plant_rows:
                for dy2 in range(-12, 13):
                    ny = pr + dy2
                    if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(col_wires)
            max_wr = max(col_wires)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE CONNECTIONS between adjacent columns ----
    conn_ys = sorted(set(active_plant_rows + [20, 35, 50, 65, 80]))
    for i in range(len(active_cols) - 1):
        c1 = active_cols[i]
        c2 = active_cols[i + 1]
        for conn_y in conn_ys:
            if not (2 <= conn_y < WORLD_H - 2):
                continue
            connected = all(
                bool(wm[conn_y, cx]) or bool(pm[conn_y, cx])
                for cx in range(c1, c2 + 1) if ib(cx, conn_y)
            )
            if not connected:
                for cx in range(c1, c2 + 1):
                    if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                        return (Tool.WIRE, cx, conn_y)

    # ---- EXTEND ROADS flanking wire spines ----
    road_half = min(47, 12 + pop // 25)
    for idx, wc in enumerate(active_cols):
        rl, rr = wc - 1, wc + 1
        col_wires = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not col_wires:
            continue
        target_top = max(2, 50 - road_half)
        target_bot = min(WORLD_H - 3, 50 + road_half)
        cycle = (step + idx * 3) % 3
        for wr in col_wires[cycle::3]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROAD CONNECTIONS between columns ----
    road_conn_ys = sorted(set(
        [pr - 1 for pr in active_plant_rows if pr - 1 >= 2] +
        [pr + 1 for pr in active_plant_rows if pr + 1 < WORLD_H - 2] +
        [23, 38, 48, 63, 73, 88]
    ))
    for conn_y in road_conn_ys:
        if not (2 <= conn_y < WORLD_H - 2):
            continue
        for i in range(len(active_cols) - 1):
            c1 = active_cols[i] - 1
            c2 = active_cols[i + 1] + 1
            c1 = max(2, c1)
            c2 = min(WORLD_W - 2, c2)
            row_roads = [c for c in range(c1, c2 + 1) if ib(c, conn_y) and bool(rm[conn_y, c])]
            if not row_roads:
                for cx in range(c1, c2 + 1):
                    if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                        return (Tool.ROAD, cx, conn_y)
            else:
                min_r2 = min(row_roads)
                max_r2 = max(row_roads)
                if min_r2 > c1:
                    for cx in range(c1, min_r2):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)
                if max_r2 < c2:
                    for cx in range(max_r2 + 1, c2 + 1):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)

    # ---- BUILD PROXIMITY MASKS ----
    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest active wire col + slight vertical centering
        best_dist = np.full(len(cxs), 999999.0)
        for wc in active_cols:
            d = (np.abs(cxs - wc).astype(float) +
                 np.abs(cys - 50).astype(float) * 0.15)
            best_dist = np.minimum(best_dist, d)

        # Also cluster near existing zones
        if total_zones > 5:
            zone_ys_a, zone_xs_a = np.where(zone_tiles)
            if len(zone_xs_a) > 0:
                zone_dist = np.full(len(cxs), 999999.0)
                step_z = max(1, len(zone_xs_a) // 60)
                for i in range(0, len(zone_xs_a), step_z):
                    d2 = np.abs(cxs - zone_xs_a[i]) + np.abs(cys - zone_ys_a[i])
                    zone_dist = np.minimum(zone_dist, d2)
                best_dist = best_dist * 0.55 + zone_dist * 0.45

        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 60:
        fire_spots = []
        for fy in range(12, 92, 15):
            for fx in range(12, 116, 22):
                fire_spots.append((fx, fy))
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = []
        for py in range(15, 90, 18):
            for px in range(10, 114, 28):
                police_spots.append((px, py))
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = []
        for sy in range(8, 95, 25):
            for sx in range(10, 115, 30):
                stadium_spots.append((sx, sy))
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [(30, 5), (60, 5), (90, 5),
                      (30, 93), (60, 93), (90, 93),
                      (5, 20), (5, 50), (5, 80),
                      (113, 20), (113, 50), (113, 80)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for ax, ay in [(55, 5), (5, 50), (113, 50), (55, 93)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for spx, spy in [(5, 90), (113, 90), (60, 95), (5, 10), (113, 10)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Parks to boost land value
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- EXTEND ROADS from existing road ends near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 100)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near any wire ----
    if len(wire_xs_arr) > 0:
        k = step % len(wire_xs_arr)
        wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
        for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx4, ny4 = wx + dx4, wy + dy4
            if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                return (Tool.ROAD, nx4, ny4)

    return None

def init(obs, state):
