    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.15:
            return Tool.INDUSTRIAL
        if c_r < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 1: Ensure power plants scattered across map ----
    # Plants at strategic locations, added as pop grows
    plant_targets = [(60, 50)]
    if pop >= 0:
        plant_targets += [(30, 30), (90, 30), (30, 70), (90, 70)]
    if pop > 100:
        plant_targets += [(60, 20), (60, 80), (20, 50), (100, 50)]
    if pop > 400:
        plant_targets += [(15, 20), (105, 20), (15, 80), (105, 80)]
        plant_targets += [(45, 15), (75, 15), (45, 85), (75, 85)]
    if pop > 800:
        plant_targets += [(30, 10), (90, 10), (30, 90), (90, 90)]
        plant_targets += [(10, 40), (110, 40), (10, 60), (110, 60)]
    if pop > 1500:
        plant_targets += [(5, 25), (115, 25), (5, 75), (115, 75)]
        plant_targets += [(55, 5), (65, 5), (55, 95), (65, 95)]
    if pop > 3000:
        plant_targets += [(20, 5), (100, 5), (20, 95), (100, 95)]
        plant_targets += [(5, 10), (115, 10), (5, 90), (115, 90)]

    for px, py in plant_targets:
        if not ib(px, py):
            continue
        # Check if a plant exists within 6 tiles
        found = False
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # ---- Phase 2: Wire network - reactive extension ----
    # Key wire corridors (rows and cols)
    wire_rows = [10, 20, 30, 50, 70, 80, 90]
    if pop > 200:
        wire_rows += [40, 60]
    if pop > 600:
        wire_rows += [15, 25, 45, 55, 75, 85]

    wire_cols = [15, 30, 60, 90, 105]
    if pop > 200:
        wire_cols += [45, 75]
    if pop > 600:
        wire_cols += [20, 52, 68, 100]
    if pop > 1200:
        wire_cols += [8, 112, 37, 83]

    # Extend horizontal wire rows - find existing wire/plant and expand
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            continue
        # Find leftmost and rightmost existing wire/plant
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Try to extend left
        target_left = 2
        if left > target_left:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Try to extend right
        target_right = WORLD_W - 3
        if right < target_right:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left, right):
            if em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Extend vertical wire cols
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        target_top = 2
        target_bot = WORLD_H - 3
        if top > target_top:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < target_bot:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot):
            if em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # ---- Phase 3: Road network - reactive extension ----
    road_rows = [8, 18, 28, 44, 56, 72, 82, 92]
    if pop > 300:
        road_rows += [36, 64]
    if pop > 700:
        road_rows += [12, 24, 48, 52, 76, 88]
    if pop > 1500:
        road_rows += [5, 95, 16, 84]

    road_cols = [14, 29, 44, 56, 76, 91, 106]
    if pop > 300:
        road_cols += [37, 83]
    if pop > 700:
        road_cols += [22, 52, 68, 98]
    if pop > 1500:
        road_cols += [7, 113, 30, 90]

    # Build horizontal roads reactively
    for rr in road_rows:
        if not ib(0, rr):
            continue
        # Only build roads near wire infrastructure
        wire_nearby = False
        for dy in range(-3, 4):
            nr = rr + dy
            if ib(0, nr) and ((wm[nr, :] | pm[nr, :]).any()):
                wire_nearby = True
                break
        if not wire_nearby:
            continue
        row_road = rm[rr, :]
        if not row_road.any():
            # Seed near a wire column
            for wc in wire_cols:
                if ib(wc, rr) and em[rr, wc] and not pm[rr, wc]:
                    return (Tool.ROAD, wc, rr)
            # Seed at center
            cx = 60
            if ib(cx, rr) and em[rr, cx]:
                return (Tool.ROAD, cx, rr)
        else:
            indices = np.where(row_road)[0]
            left = int(indices[0])
            right = int(indices[-1])
            target_left = 3
            target_right = WORLD_W - 4
            if left > target_left and em[rr, left-1] and not pm[rr, left-1]:
                return (Tool.ROAD, left-1, rr)
            if right < target_right and em[rr, right+1] and not pm[rr, right+1]:
                return (Tool.ROAD, right+1, rr)

    # Build vertical roads reactively
    for rc in road_cols:
        if not ib(rc, 0):
            continue
        wire_nearby = False
        for dx in range(-3, 4):
            nc = rc + dx
            if ib(nc, 0) and ((wm[:, nc] | pm[:, nc]).any()):
                wire_nearby = True
                break
        if not wire_nearby:
            continue
        col_road = rm[:, rc]
        if not col_road.any():
            for wr in wire_rows:
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            cy = 50
            if ib(rc, cy) and em[cy, rc]:
                return (Tool.ROAD, rc, cy)
        else:
            indices = np.where(col_road)[0]
            top = int(indices[0])
            bot = int(indices[-1])
            target_top = 3
            target_bot = WORLD_H - 4
            if top > target_top and em[top-1, rc] and not pm[top-1, rc]:
                return (Tool.ROAD, rc, top-1)
            if bot < target_bot and em[bot+1, rc] and not pm[bot+1, rc]:
                return (Tool.ROAD, rc, bot+1)

    # ---- Phase 4: Zone placement (reactive, near roads + wire) ----
    # Compute road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    # Keep border margin for 3x3 zones
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: closer to existing zones = better (cluster growth)
        # Also prefer spots closer to power plants
        min_plant_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in plant_targets[:8]:  # limit for speed
            if ib(px, py):
                d = np.abs(cxs_arr - px).astype(float) + np.abs(cys_arr - py).astype(float)
                min_plant_dist = np.minimum(min_plant_dist, d)

        zone_score = np.zeros(len(cxs_arr))
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist * 0.6 + min_plant_dist * 0.4
            else:
                zone_score = min_plant_dist
        else:
            zone_score = min_plant_dist

        order = np.argsort(zone_score)
        # Offset for variety
        off = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---- Phase 5: Civic services ----
    if pop > 30:
        fire_spots = [
            (58, 38), (62, 38), (58, 62), (62, 62),
            (28, 40), (92, 40), (28, 60), (92, 60),
            (40, 25), (80, 25), (40, 75), (80, 75),
            (15, 48), (105, 48), (15, 52), (105, 52),
            (58, 15), (62, 15), (58, 85), (62, 85),
            (25, 15), (95, 15), (25, 85), (95, 85),
            (10, 30), (110, 30), (10, 70), (110, 70),
            (45, 8), (75, 8), (45, 92), (75, 92),
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [
            (55, 42), (65, 42), (55, 58), (65, 58),
            (26, 36), (94, 36), (26, 64), (94, 64),
            (38, 22), (82, 22), (38, 78), (82, 78),
            (12, 50), (108, 50),
            (50, 12), (70, 12), (50, 88), (70, 88),
            (18, 20), (102, 20), (18, 80), (102, 80),
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [
            (60, 46), (60, 54), (50, 50), (70, 50),
            (40, 38), (80, 38), (40, 62), (80, 62),
            (30, 22), (90, 22), (30, 78), (90, 78),
            (20, 45), (100, 45), (20, 55), (100, 55),
            (60, 25), (60, 75),
        ]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        for stx, sty in [
            (44, 32), (76, 32), (44, 68), (76, 68),
            (22, 46), (98, 46), (22, 54), (98, 54),
            (60, 18), (60, 82),
            (12, 20), (108, 20), (12, 80), (108, 80),
            (35, 8), (85, 8), (35, 92), (85, 92),
        ]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        for apx, apy in [
            (54, 6), (66, 6), (54, 94), (66, 94),
            (7, 36), (113, 36), (7, 64), (113, 64),
            (25, 6), (95, 6),
        ]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        for spx, spy in [
            (6, 50), (114, 50), (60, 3), (60, 97),
            (20, 3), (100, 3), (20, 97), (100, 97),
            (5, 15), (115, 15), (5, 85), (115, 85),
        ]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend wire near existing plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 50)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: extend road near wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 80)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0,1),(0,-1),(1,0),(-1,0),(2,0),(-2,0),(0,2),(0,-2)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + seed roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(62, 90):
        actions.append((Tool.WIRE, x, 50))
    for x in range(32, 58):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(35, 48):
        actions.append((Tool.WIRE, 60, y))
    for y in range(52, 65):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads flanking vertical spine
    for y in range(35, 65):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    # Horizontal seed roads
    for x in range(40, 80):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Track phase in state
    if 'phase' not in state:
        state['phase'] = 'build_infra'
        state['plant_index'] = 0
        state['wire_queue'] = []
        state['road_queue'] = []

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define plant locations - placed progressively as pop grows
    all_plant_locs = [
        (60, 50),   # center (init)
        (20, 25),   # top-left
        (100, 25),  # top-right
        (20, 75),   # bottom-left
        (100, 75),  # bottom-right
        (60, 15),   # top-center
        (60, 85),   # bottom-center
        (10, 50),   # far left
        (110, 50),  # far right
        (35, 50),   # mid-left
        (85, 50),   # mid-right
    ]

    # Determine how many plants to target based on pop
    def target_plant_count():
        if pop < 100: return 1
        if pop < 300: return 3
        if pop < 600: return 5
        if pop < 1000: return 7
        if pop < 2000: return 9
        return 11

    target_plants = all_plant_locs[:target_plant_count()]

    # Ensure all target plants exist
    for px, py in target_plants:
        if not ib(px, py):
            continue
        found = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = px+dx, py+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # Build wire grid: horizontal spines at key rows
    wire_rows = [25, 35, 44, 50, 56, 65, 75]
    if pop > 300:
        wire_rows += [15, 85]
    if pop > 800:
        wire_rows += [10, 90]

    # Wire columns at key columns
    wire_cols = [20, 35, 60, 85, 100]
    if pop > 200:
        wire_cols += [10, 110]
    if pop > 600:
        wire_cols += [45, 75]

    # Fill horizontal wire spines
    for wr in wire_rows:
        if not ib(0, wr): continue
        for x in range(2, WORLD_W-2):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                # Only extend if adjacent to existing wire/plant
                has_nbr = False
                for ddx in [-1, 1]:
                    nx2 = x + ddx
                    if ib(nx2, wr) and (wm[wr, nx2] or pm[wr, nx2]):
                        has_nbr = True
                        break
                if has_nbr:
                    return (Tool.WIRE, x, wr)

    # Fill vertical wire spines
    for wc in wire_cols:
        if not ib(wc, 0): continue
        for y in range(2, WORLD_H-2):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                has_nbr = False
                for ddy in [-1, 1]:
                    ny2 = y + ddy
                    if ib(wc, ny2) and (wm[ny2, wc] or pm[ny2, wc]):
                        has_nbr = True
                        break
                if has_nbr:
                    return (Tool.WIRE, wc, y)

    # Build road grid
    # Horizontal roads one row above/below each wire row
    road_rows = []
    for wr in wire_rows:
        for off in [-1, 1]:
            rr = wr + off
            if 3 <= rr <= WORLD_H-4:
                road_rows.append(rr)

    # Vertical roads one col left/right of each wire col
    road_cols = []
    for wc in wire_cols:
        for off in [-1, 1]:
            rc = wc + off
            if 3 <= rc <= WORLD_W-4:
                road_cols.append(rc)

    # Fill horizontal roads
    for hr in road_rows:
        if not ib(0, hr): continue
        # Check if wire is nearby (1 row above or below)
        wire_near = False
        for dy2 in [-2, -1, 1, 2]:
            ny2 = hr + dy2
            if ib(0, ny2) and (wm[ny2, :] | pm[ny2, :]).any():
                wire_near = True
                break
        if not wire_near:
            continue
        for x in range(3, WORLD_W-3):
            if ib(x, hr) and em[hr, x] and not pm[hr, x]:
                return (Tool.ROAD, x, hr)

    # Fill vertical roads
    for vr in road_cols:
        if not ib(vr, 0): continue
        wire_near = False
        for dx2 in [-2, -1, 1, 2]:
            nx2 = vr + dx2
            if ib(nx2, 0) and (wm[:, nx2] | pm[:, nx2]).any():
                wire_near = True
                break
        if not wire_near:
            continue
        for y in range(3, WORLD_H-3):
            if ib(vr, y) and em[y, vr] and not pm[y, vr]:
                return (Tool.ROAD, vr, y)

    # === Zone placement (closed-loop, proximity-based) ===
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by distance to nearest plant (prefer close) + some diversity via step offset
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in target_plants:
            d = np.abs(cxs_arr - px).astype(float) + np.abs(cys_arr - py).astype(float)
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = (step * 3) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # === Services (closed-loop, placed when pop warrants) ===
    if pop > 80:
        fire_locs = [(57, 38), (63, 38), (57, 62), (63, 62),
                     (17, 22), (23, 22), (97, 22), (103, 22),
                     (17, 72), (23, 72), (97, 72), (103, 72)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 250:
        police_locs = [(55, 40), (65, 40), (55, 60), (65, 60),
                       (15, 25), (25, 25), (95, 25), (105, 25),
                       (15, 73), (25, 73), (95, 73), (105, 73)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        for stx, sty in [(40, 30), (80, 30), (40, 70), (80, 70), (60, 50)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 900:
        for apx, apy in [(55, 12), (55, 88), (10, 45), (110, 45)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        for spx, spy in [(5, 50), (115, 50), (60, 5), (60, 95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend roads near wire
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants spread across middle row with wire+road spines."""
    actions = []
    # Four plants across the map
    for px in [15, 45, 75, 105]:
        actions.append((Tool.COALPOWER, px, 50))
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, 50 + dy))
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- ACTIVE WIRE COLUMNS based on population ----
    # 8 wire columns across the 120-wide map
    all_wire_cols = [12, 27, 42, 57, 72, 87, 102, 117]

    def num_active_cols():
        if pop < 50:   return 2
        if pop < 150:  return 3
        if pop < 400:  return 4
        if pop < 800:  return 5
        if pop < 1500: return 6
        if pop < 3000: return 7
        return 8

    n_cols = num_active_cols()
    active_cols = all_wire_cols[:n_cols]

    # Plant rows: we want plants at multiple y-levels per column
    all_plant_rows = [20, 50, 80]

    def num_plant_rows():
        if pop < 200:  return 1
        if pop < 800:  return 2
        return 3

    n_prows = num_plant_rows()
    active_plant_rows = all_plant_rows[:n_prows]

    # ---- BUILD PROXIMITY MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ENSURE POWER PLANTS per active column + row ----
    for wc in active_cols:
        for pr in active_plant_rows:
            has_plant = False
            for dx in range(-8, 9):
                for dy in range(-8, 9):
                    nx, ny = wc + dx, pr + dy
                    if ib(nx, ny) and bool(pm[ny, nx]):
                        has_plant = True
                        break
                if has_plant:
                    break
            if not has_plant:
                for r in range(0, 12):
                    placed = False
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if r > 0 and abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = wc + dx2, pr + dy2
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # ---- EXTEND WIRE SPINES vertically ----
    spine_half = min(45, 12 + pop // 15)
    for wc in active_cols:
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            # Seed wire near first plant row
            for pr in active_plant_rows:
                for dy2 in range(-6, 7):
                    ny = pr + dy2
                    if ib(wc, ny) and (bool(em[ny, wc]) or bool(wm[ny, wc])) and not bool(pm[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            target_top = max(2, 50 - spine_half)
            target_bot = min(WORLD_H - 3, 50 + spine_half)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE CONNECTIONS between neighboring columns ----
    # Connect at multiple y-levels
    h_wire_rows = [20, 35, 50, 65, 80]
    for i in range(len(active_cols) - 1):
        c1 = active_cols[i]
        c2 = active_cols[i + 1]
        for conn_y in h_wire_rows:
            for cx in range(c1, c2 + 1):
                if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                    return (Tool.WIRE, cx, conn_y)

    # ---- EXTEND ROADS flanking wire spines ----
    road_half = min(45, 10 + pop // 20)
    for idx, wc in enumerate(active_cols):
        rl, rr = wc - 1, wc + 1
        if not ib(rl, 0) and not ib(rr, 0):
            continue
        wire_in_col = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not wire_in_col:
            continue
        target_top = max(2, 50 - road_half)
        target_bot = min(WORLD_H - 3, 50 + road_half)
        cycle = (step + idx * 3) % 3
        for wr in wire_in_col[cycle::3]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROAD CONNECTIONS between columns ----
    if pop > 60:
        h_road_rows = [18, 33, 48, 63, 78]
        for conn_y in h_road_rows:
            road_in_row = [c for c in range(WORLD_W) if ib(c, conn_y) and bool(rm[conn_y, c])]
            if not road_in_row:
                continue
            min_r = min(road_in_row)
            max_r = max(road_in_row)
            for wc in sorted(active_cols):
                target_l = wc - 1
                if target_l < min_r:
                    for cx in range(target_l, min_r):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)
            for wc in sorted(active_cols, reverse=True):
                target_r = wc + 1
                if target_r > max_r:
                    for cx in range(max_r + 1, target_r + 1):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for wc in active_cols:
            d = (np.abs(cxs - wc).astype(float)
                 + np.abs(cys - 50).astype(float) * 0.25)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- EXTEND ROADS from existing road tiles near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 80:
        fire_spots = [
            (25, 25), (55, 25), (85, 25), (115, 25),
            (10, 50), (40, 50), (70, 50), (100, 50),
            (25, 75), (55, 75), (85, 75), (115, 75),
            (10, 10), (60, 10), (110, 10),
            (10, 90), (60, 90), (110, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [
            (20, 20), (50, 20), (80, 20), (110, 20),
            (20, 50), (50, 50), (80, 50), (110, 50),
            (20, 80), (50, 80), (80, 80), (110, 80),
            (5, 35), (5, 65), (115, 35), (115, 65),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 900:
        stadium_spots = [
            (30, 10), (70, 10), (110, 10),
            (30, 90), (70, 90), (110, 90),
            (5, 30), (5, 70), (115, 30), (115, 70),
            (50, 50), (70, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1800:
        nuke_spots = [
            (30, 8), (70, 8), (110, 8),
            (30, 92), (70, 92), (110, 92),
            (5, 25), (5, 75), (115, 25), (115, 75),
            (55, 50), (85, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        for ax, ay in [(60, 7), (5, 50), (115, 50), (60, 93)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sx2, sy2 in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 250:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 20)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3),
                                  (4, 0), (0, 4), (-4, 0), (0, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place coal plant somewhere empty ----
    plant_ys, plant_xs = np.where(em)
    if len(plant_xs) > 0:
        k = (step * 7) % len(plant_xs)
        return (Tool.COALPOWER, int(plant_xs[k]), int(plant_ys[k]))

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in a diamond, wires connecting them, seed roads"""
    actions = []
    # 4 plants at cardinal positions around center
    plants = [(30, 35), (90, 35), (30, 65), (90, 65)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire horizontal spine at y=50
    for x in range(32, 89):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertical spines
    for y in range(37, 64):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Connect plants to horizontal spine
    for y in range(37, 51):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads flanking wire spines
    for y in range(37, 64):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
        actions.append((Tool.ROAD, 89, y))
        actions.append((Tool.ROAD, 91, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Track phase in state
    if 'phase' not in state:
        state['phase'] = 0
    if 'extra_plants' not in state:
        state['extra_plants'] = set()

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Primary plant locations (4 corners of inner city + extras) ----
    base_plants = [(30, 35), (90, 35), (30, 65), (90, 65)]
    # Additional plants as city grows
    extra_plant_candidates = [
        (60, 20), (60, 80), (15, 50), (105, 50),
        (45, 20), (75, 20), (45, 80), (75, 80),
        (15, 35), (105, 35), (15, 65), (105, 65),
        (60, 50),  # center last
    ]

    # ---- Ensure base plants exist ----
    for px, py in base_plants:
        found = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # ---- Add extra plants at population thresholds ----
    thresholds = [100, 300, 600, 1000, 1500, 2000, 3000, 4000, 5000, 6000, 7000, 8000]
    needed_extras = 0
    for i, thr in enumerate(thresholds):
        if pop >= thr:
            needed_extras = i + 1
    needed_extras = min(needed_extras, len(extra_plant_candidates))

    for i in range(needed_extras):
        epx, epy = extra_plant_candidates[i]
        key = (epx, epy)
        if key in state['extra_plants']:
            continue
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = epx + dx, epy + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            state['extra_plants'].add(key)
            return (Tool.COALPOWER, epx, epy)

    # ---- Build comprehensive wire network ----
    # Connect all plants with wires along horizontal and vertical corridors
    # Wire at rows 35, 50, 65 and cols 30, 60, 90
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    # Extend wire rows
    for wr in wire_rows:
        for wx in range(1, WORLD_W - 1):
            if ib(wx, wr) and em[wr, wx] and not pm[wr, wx]:
                # Check neighbors have wire
                if (ib(wx-1, wr) and (wm[wr, wx-1] or pm[wr, wx-1])) or \
                   (ib(wx+1, wr) and (wm[wr, wx+1] or pm[wr, wx+1])):
                    return (Tool.WIRE, wx, wr)

    # Extend wire cols
    for wc in wire_cols:
        for wy in range(1, WORLD_H - 1):
            if ib(wc, wy) and em[wy, wc] and not pm[wy, wc]:
                if (ib(wc, wy-1) and (wm[wy-1, wc] or pm[wy-1, wc])) or \
                   (ib(wc, wy+1) and (wm[wy+1, wc] or pm[wy+1, wc])):
                    return (Tool.WIRE, wc, wy)

    # ---- Build road network ----
    # Roads parallel to wire spines (offset by 1)
    road_rows = [19, 34, 49, 64, 79]  # slightly offset from wire rows
    road_cols = [14, 29, 44, 59, 74, 89, 104]

    # Horizontal roads
    for rr in road_rows:
        for rx in range(1, WORLD_W - 1):
            if ib(rx, rr) and em[rr, rx] and not pm[rr, rx]:
                if (ib(rx-1, rr) and rm[rr, rx-1]) or (ib(rx+1, rr) and rm[rr, rx+1]):
                    return (Tool.ROAD, rx, rr)

    # Vertical roads
    for rc in road_cols:
        for ry in range(1, WORLD_H - 1):
            if ib(rc, ry) and em[ry, rc] and not pm[ry, rc]:
                if (ib(rc, ry-1) and rm[ry-1, rc]) or (ib(rc, ry+1) and rm[ry+1, rc]):
                    return (Tool.ROAD, rc, ry)

    # ---- Proximity masks ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    # Safe margins
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Don't place on wire rows or road rows
    for wr in wire_rows + road_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols + road_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Multiple cluster centers to spread placement
        centers = [(30, 35), (90, 35), (30, 65), (90, 65),
                   (60, 50), (15, 50), (105, 50), (60, 20), (60, 80)]
        min_dist = np.full(len(cxs_arr), 999999.0)
        for cx_c, cy_c in centers:
            d = np.abs(cxs_arr - cx_c) + np.abs(cys_arr - cy_c)
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = int(step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- Services at thresholds ----
    if pop > 200:
        service_spots = [
            (25, 30), (55, 30), (85, 30), (110, 30),
            (25, 70), (55, 70), (85, 70), (110, 70),
            (10, 50), (25, 50), (55, 50), (85, 50),
        ]
        for fsx, fsy in service_spots:
            if ib(fsx, fsy) and em[fsy, fsx]:
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 600:
        police_spots = [
            (20, 28), (60, 28), (100, 28),
            (20, 72), (60, 72), (100, 72),
            (10, 45), (110, 45), (10, 55), (110, 55),
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and em[psy, psx]:
                return (Tool.POLICESTATION, psx, psy)

    if pop > 1500:
        for stx, sty in [(35, 25), (85, 25), (35, 75), (85, 75), (60, 45), (60, 55)]:
            if ib(stx, sty) and em[sty, stx]:
                return (Tool.STADIUM, stx, sty)

    if pop > 3000:
        for apx, apy in [(55, 15), (55, 85), (10, 30), (110, 30)]:
            if ib(apx, apy) and em[apy, apx]:
                return (Tool.AIRPORT, apx, apy)

    if pop > 5000:
        for spx, spy in [(10, 80), (110, 80), (10, 20), (110, 20)]:
            if ib(spx, spy) and em[spy, spx]:
                return (Tool.SEAPORT, spx, spy)

    # ---- Add roads near existing wires as fallback ----
    wy_arr, wx_arr = np.where(wm)
    if len(wx_arr) > 0:
        step_k = int(step * 11) % len(wx_arr)
        for offset in range(min(len(wx_arr), 40)):
            k = (step_k + offset * 7) % len(wx_arr)
            wwx, wwy = int(wx_arr[k]), int(wy_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wwx + dx2, wwy + dy2
                if ib(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # ---- Expand wires from existing wires ----
    if len(wx_arr) > 0:
        step_k2 = int(step * 13) % len(wx_arr)
        for offset in range(min(len(wx_arr), 30)):
            k = (step_k2 + offset * 5) % len(wx_arr)
            wwx2, wwy2 = int(wx_arr[k]), int(wy_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wwx2 + dx3, wwy2 + dy3
                if ib(nx3, ny3) and em[ny3, nx3] and not pm[ny3, nx3]:
                    return (Tool.WIRE, nx3, ny3)

    return None

