def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- ANCHOR GRID: 5 columns x 4 rows = 20 neighborhoods ----
    # Each anchor: (plant_x, plant_y, wire_col)
    # Wire column is plant_x+2, roads at wire_col±1
    anchor_xs = [10, 30, 55, 80, 105]
    anchor_ys = [15, 38, 62, 85]
    anchors = []
    for ax in anchor_xs:
        for ay in anchor_ys:
            wc = ax + 2
            anchors.append((ax, ay, wc, wc - 1, wc + 1))

    # Unlock anchors progressively
    def num_active():
        if pop < 50:   return 3
        if pop < 200:  return 5
        if pop < 500:  return 8
        if pop < 1000: return 12
        if pop < 2000: return 16
        return 20

    active = anchors[:num_active()]

    # ---- ENSURE POWER PLANTS for each active anchor ----
    for (px, py, wc, rl, rr) in active:
        # Check if there's a plant within 4 tiles of anchor
        x0, x1 = max(0, px - 4), min(WORLD_W, px + 5)
        y0, y1 = max(0, py - 4), min(WORLD_H, py + 5)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant at anchor
            if ib(px, py):
                return (Tool.COALPOWER, px, py)

    # ---- BUILD WIRE SPINES for each active anchor ----
    # Spine extends from py-18 to py+18 along wire_col
    for (px, py, wc, rl, rr) in active:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 18)
        spine_bot = min(WORLD_H - 3, py + 18)

        # Find existing wire in this column within spine range
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(wc, r) and bool(wm[r, wc])]

        if not col_wire:
            # Seed wire adjacent to plant (not on plant)
            for dy in range(-2, 3):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_w = min(col_wire)
            max_w = max(col_wire)
            # Extend downward
            if max_w < spine_bot:
                nr = max_w + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)
            # Extend upward
            if min_w > spine_top:
                nr = min_w - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE between adjacent same-row anchors ----
    for i in range(len(active)):
        for j in range(i + 1, len(active)):
            px1, py1, wc1, _, _ = active[i]
            px2, py2, wc2, _, _ = active[j]
            if py1 == py2 and abs(wc1 - wc2) < 30:
                min_wc = min(wc1, wc2)
                max_wc = max(wc1, wc2)
                for cx in range(min_wc, max_wc + 1):
                    if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                        return (Tool.WIRE, cx, py1)

    # ---- ROAD BUILDING flanking wire spines ----
    for (px, py, wc, rl, rr) in active:
        col_wire = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not col_wire:
            continue
        cycle = step % 3
        for wr in col_wire[cycle::3]:
            # Road on left side
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            # Road on right side
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS connecting anchors at multiple y-levels ----
    # Connect roads horizontally between anchors in same row
    for i in range(len(active) - 1):
        px1, py1, wc1, rl1, rr1 = active[i]
        px2, py2, wc2, rl2, rr2 = active[i + 1]
        if py1 == py2 and abs(px1 - px2) < 35:
            for cx in range(min(rr1, rl2), max(rr1, rl2) + 1):
                if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                    return (Tool.ROAD, cx, py1)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # target: 25% ind, 25% com, 50% res
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute neighbor proximity masks (vectorized)
    # nbr_road: any road within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = r0 + (sr1 - sr0)
            c0 = max(0, dx2); c1 = c0 + (sc1 - sc0)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # nbr_wire: any wire or plant within 6 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = r0 + (sr1 - sr0)
            c0 = max(0, dx2); c1 = c0 + (sc1 - sc0)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep border safe
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates by closeness to active anchor wire columns
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active:
            d = np.abs(cxs.astype(float) - wc) + np.abs(cys.astype(float) - py)
            np.minimum(best_dist, d, out=best_dist)
        order = np.argsort(best_dist)
        # Use step offset for variety
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS outward from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 50)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with population ----
    if pop > 200:
        fire_spots = [
            (35, 50), (65, 50), (95, 50),
            (35, 25), (65, 25), (95, 25),
            (35, 75), (65, 75), (95, 75),
            (15, 38), (15, 62), (50, 15), (50, 85),
            (80, 15), (80, 85), (110, 38), (110, 62),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = [
            (40, 43), (70, 43), (100, 43),
            (40, 57), (70, 57), (100, 57),
            (25, 30), (25, 70), (55, 8), (55, 92),
            (85, 8), (85, 92), (112, 30), (112, 70),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadium_spots = [
            (50, 50), (80, 25), (20, 75), (100, 75),
            (20, 25), (100, 25),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        # Add seaport/airport for big cities
        for (sx, sy) in [(10, 10), (110, 10), (10, 90), (110, 90)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants with wire spines and flanking roads."""
