def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    step = obs.step
    pop = obs.city_pop

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- State initialization ---
    if 'phase' not in state:
        state['phase'] = 'infra'
        state['plant_list'] = [(60, 50)]
        state['wire_queue'] = []
        state['road_queue'] = []
        state['zone_idx'] = 0

    # --- Dynamic plant expansion ---
    # Add plants as population grows
    target_plants = [(60, 50)]
    if pop >= 50 or step > 100:
        target_plants += [(20, 25), (100, 25)]
    if pop >= 200 or step > 300:
        target_plants += [(20, 75), (100, 75)]
    if pop >= 500 or step > 600:
        target_plants += [(60, 15), (60, 85)]
    if pop >= 1000 or step > 900:
        target_plants += [(40, 50), (80, 50)]
    if pop >= 2000 or step > 1200:
        target_plants += [(10, 50), (110, 50), (60, 35), (60, 65)]

    state['plant_list'] = target_plants

    # --- Ensure all target plants exist ---
    for px, py in target_plants:
        # Check vicinity for a plant
        found = any(
            ib(px+dx, py+dy) and pm[py+dy, px+dx]
            for dx in range(-4, 5) for dy in range(-4, 5)
        )
        if not found and ib(px, py):
            return (Tool.COALPOWER, px, py)

    # --- Wire network: connect plants with a grid ---
    # Main horizontal spine at rows 25, 50, 75
    # Main vertical spine at cols 20, 60, 100
    spine_rows = [25, 50, 75]
    spine_cols = [20, 60, 100]
    if pop >= 300 or step > 400:
        spine_rows += [15, 35, 65, 85]
        spine_cols += [40, 80]
    if pop >= 800 or step > 800:
        spine_rows += [10, 90]
        spine_cols += [10, 110]

    # Build horizontal wire spines
    for row in spine_rows:
        if not ib(0, row):
            continue
        for x in range(1, WORLD_W - 1):
            if em[row, x] and not pm[row, x] and not wm[row, x]:
                # Only place if adjacent to wire or plant
                adj = (
                    (ib(x-1, row) and (wm[row, x-1] or pm[row, x-1])) or
                    (ib(x+1, row) and (wm[row, x+1] or pm[row, x+1]))
                )
                if adj:
                    return (Tool.WIRE, x, row)

    # Build vertical wire spines
    for col in spine_cols:
        if not ib(col, 0):
            continue
        for y in range(1, WORLD_H - 1):
            if em[y, col] and not pm[y, col] and not wm[y, col]:
                adj = (
                    (ib(col, y-1) and (wm[y-1, col] or pm[y-1, col])) or
                    (ib(col, y+1) and (wm[y+1, col] or pm[y+1, col]))
                )
                if adj:
                    return (Tool.WIRE, col, y)

    # --- Road grid: parallel to wire spines, offset by 1 ---
    road_rows = [r + 1 for r in spine_rows] + [r - 1 for r in spine_rows]
    road_cols = [c + 1 for c in spine_cols] + [c - 1 for c in spine_cols]

    # Build horizontal roads
    for row in sorted(set(road_rows)):
        if not ib(0, row):
            continue
        # Only build roads where there's wire nearby (above or below)
        has_wire_nearby = (
            (row > 0 and (wm[row-1, :] | pm[row-1, :]).any()) or
            (row < WORLD_H-1 and (wm[row+1, :] | pm[row+1, :]).any())
        )
        if not has_wire_nearby:
            continue
        for x in range(2, WORLD_W - 2):
            if ib(x, row) and em[row, x] and not pm[row, x] and not rm[row, x]:
                # Build if adjacent to road or near wire
                adj_road = (
                    (ib(x-1, row) and rm[row, x-1]) or
                    (ib(x+1, row) and rm[row, x+1])
                )
                if adj_road:
                    return (Tool.ROAD, x, row)

    # Build vertical roads
    for col in sorted(set(road_cols)):
        if not ib(col, 0):
            continue
        has_wire_nearby = (
            (col > 0 and (wm[:, col-1] | pm[:, col-1]).any()) or
            (col < WORLD_W-1 and (wm[:, col+1] | pm[:, col+1]).any())
        )
        if not has_wire_nearby:
            continue
        for y in range(2, WORLD_H - 2):
            if ib(col, y) and em[y, col] and not pm[y, col] and not rm[y, col]:
                adj_road = (
                    (ib(col, y-1) and rm[y-1, col]) or
                    (ib(col, y+1) and rm[y+1, col])
                )
                if adj_road:
                    return (Tool.ROAD, col, y)

    # --- Zone placement ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: ~50% res, ~25% com, ~25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Prioritize near plant hubs for power, but spread across map
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in target_plants:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)
        # Also favor spread: penalize clustering
        order = np.argsort(min_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Services based on population ---
    if pop > 80:
        fire_spots = [
            (58, 35), (62, 35), (18, 22), (22, 22), (98, 22), (102, 22),
            (18, 72), (22, 72), (98, 72), (102, 72),
            (58, 65), (62, 65)
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 250:
        police_spots = [
            (55, 40), (65, 40), (15, 28), (25, 28),
            (95, 28), (105, 28), (15, 68), (25, 68),
            (95, 68), (105, 68), (55, 60), (65, 60)
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        for stx, sty in [(38, 38), (82, 38), (38, 62), (82, 62), (60, 20), (60, 80)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 900:
        for apx, apy in [(30, 10), (90, 10), (30, 90), (90, 90)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        for spx, spy in [(5, 50), (115, 50), (60, 5), (60, 95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire ---
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants spread across the map with wire and road spines."""
    actions = []
    # Six plants: 2 rows x 3 columns
    plant_positions = [(20, 35), (60, 35), (100, 35), (20, 65), (60, 65), (100, 65)]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More aggressive zone mix: 35% ind, 30% com, 35% res
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.35:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6-cluster layout: 2 rows x 3 cols, each with its own wire+road spine
    cluster_centers = [(20, 35), (60, 35), (100, 35), (20, 65), (60, 65), (100, 65)]

    # Scale number of active clusters with population
    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 300:  return 3
        if pop < 600:  return 4
        if pop < 1000: return 5
        return 6

    n_active = num_active()
    active_centers = cluster_centers[:n_active]

    # --- ENSURE POWER PLANTS ---
    for (px, py) in active_centers:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE SPINE (vertical) per cluster ---
    spine_half = min(25, 8 + pop // 15)
    for (px, py) in active_centers:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(px, r) and bool(wm[r, px])]
        if not wire_rows:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # --- HORIZONTAL WIRE connecting clusters in same row ---
    row_ys = sorted(set(py for (px, py) in active_centers))
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl], key=lambda a: a[0])
        for i in range(len(row_cs) - 1):
            x1c = row_cs[i][0]
            x2c = row_cs[i + 1][0]
            for cx in range(x1c + 1, x2c):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting rows ---
    if n_active >= 4:
        col_xs = sorted(set(px for (px, py) in active_centers))
        for xc in col_xs:
            col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc], key=lambda a: a[1])
            for i in range(len(col_cs) - 1):
                y1c = col_cs[i][1]
                y2c = col_cs[i + 1][1]
                for cy in range(y1c + 1, y2c):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # --- ROAD flanking wire spines ---
    for idx, (px, py) in enumerate(active_centers):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(px, r) and bool(wm[r, px])]
        if not wire_rows:
            continue
        rl = px - 1
        rr = px + 1
        cycle = (step + idx * 5) % 3
        for wr in wire_rows[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # --- HORIZONTAL ROADS connecting clusters at row y-levels ---
    if pop > 30:
        for yl in row_ys:
            row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl], key=lambda a: a[0])
            if len(row_cs) < 2:
                continue
            x_left = row_cs[0][0] - 1
            x_right = row_cs[-1][0] + 1
            for horiz_y in [yl - 3, yl + 3]:
                if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                    continue
                for cx in range(x_left, x_right + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # --- ADDITIONAL HORIZONTAL ROADS at mid-points between clusters ---
    if pop > 200:
        for yl in row_ys:
            row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl], key=lambda a: a[0])
            if len(row_cs) < 2:
                continue
            x_left = row_cs[0][0] - 1
            x_right = row_cs[-1][0] + 1
            for horiz_y in [yl - 6, yl + 6]:
                if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                    continue
                for cx in range(x_left, x_right + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_centers:
            d = (np.abs(cxs - px).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 1.0)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES: fire stations early and often ---
    if pop > 80:
        fire_spots = [
            (8, 25), (30, 25), (50, 25), (70, 25), (90, 25), (112, 25),
            (8, 45), (30, 45), (50, 45), (70, 45), (90, 45), (112, 45),
            (8, 55), (30, 55), (50, 55), (70, 55), (90, 55), (112, 55),
            (8, 75), (30, 75), (50, 75), (70, 75), (90, 75), (112, 75),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (15, 20), (45, 20), (75, 20), (105, 20),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 80), (45, 80), (75, 80), (105, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (35, 10), (75, 10), (115, 10),
            (35, 90), (75, 90), (5, 50),
            (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power for extra capacity
    if pop > 1000:
        nuke_spots = [
            (40, 5), (80, 5), (5, 50), (115, 50),
            (40, 95), (80, 95), (5, 20), (115, 20),
            (5, 80), (115, 80),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS to boost land value ---
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 25)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- FALLBACK: extend wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire spines and flanking roads."""
    actions = []
