    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Balance: 50% RES, 30% COM, 20% IND
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 1: Power plants ----
    # Grid of plants across map, deployed progressively
    plant_grid = []
    # Core 5 plants (always)
    plant_grid += [(30, 25), (90, 25), (60, 50), (30, 75), (90, 75)]
    # Additional plants as pop grows
    if pop >= 0:
        plant_grid += [(60, 15), (60, 85), (15, 50), (105, 50)]
    if pop > 200:
        plant_grid += [(15, 20), (105, 20), (15, 80), (105, 80)]
        plant_grid += [(45, 40), (75, 40), (45, 60), (75, 60)]
    if pop > 500:
        plant_grid += [(30, 10), (60, 10), (90, 10)]
        plant_grid += [(30, 90), (60, 90), (90, 90)]
        plant_grid += [(10, 35), (10, 65), (110, 35), (110, 65)]
    if pop > 1000:
        plant_grid += [(20, 50), (100, 50), (40, 20), (80, 20), (40, 80), (80, 80)]
        plant_grid += [(5, 25), (5, 75), (115, 25), (115, 75)]
    if pop > 2000:
        plant_grid += [(20, 10), (100, 10), (20, 90), (100, 90)]
        plant_grid += [(50, 5), (70, 5), (50, 95), (70, 95)]
        plant_grid += [(5, 10), (115, 10), (5, 90), (115, 90)]

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        found = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = px+dx, py+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # ---- Phase 2: Wire network ----
    # Dense wire grid: rows every 10 tiles, cols every 15 tiles
    wire_rows_base = list(range(10, 95, 10))  # 10,20,30,40,50,60,70,80,90
    wire_cols_base = list(range(10, 115, 15))  # 10,25,40,55,70,85,100,115

    wire_rows = wire_rows_base[:]
    wire_cols = wire_cols_base[:]
    if pop > 400:
        wire_rows += [15, 25, 35, 45, 55, 65, 75, 85]
        wire_cols += [17, 32, 47, 62, 77, 92, 107]
    if pop > 1000:
        wire_rows += [5, 95]
        wire_cols += [5, 60, 115]

    # Extend horizontal wires
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        if right < WORLD_W - 3:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        for x in range(left, right):
            if em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Extend vertical wires
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 3:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot):
            if em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # ---- Phase 3: Road network ----
    # Dense road grid between wire rows
    road_rows_base = [8, 12, 18, 22, 28, 32, 38, 43, 47, 53, 57, 62, 67, 72, 78, 83, 87, 92]
    road_cols_base = [7, 13, 20, 27, 35, 42, 50, 58, 65, 72, 80, 88, 95, 102, 110]

    road_rows = road_rows_base[:]
    road_cols = road_cols_base[:]
    if pop > 600:
        road_rows += [5, 95, 15, 85]
        road_cols += [4, 116, 30, 90]
    if pop > 1500:
        road_rows += [3, 97]
        road_cols += [2, 118]

    # Build horizontal roads near wire
    for rr in road_rows:
        if not ib(0, rr):
            continue
        wire_nearby = False
        for dy in range(-4, 5):
            nr = rr + dy
            if 0 <= nr < WORLD_H and ((wm[nr, :] | pm[nr, :]).any()):
                wire_nearby = True
                break
        if not wire_nearby:
            continue
        row_road = rm[rr, :]
        if not row_road.any():
            for wc in wire_cols_base:
                if ib(wc, rr) and em[rr, wc] and not pm[rr, wc]:
                    return (Tool.ROAD, wc, rr)
            if ib(60, rr) and em[rr, 60]:
                return (Tool.ROAD, 60, rr)
        else:
            indices = np.where(row_road)[0]
            left = int(indices[0])
            right = int(indices[-1])
            if left > 3 and em[rr, left-1] and not pm[rr, left-1]:
                return (Tool.ROAD, left-1, rr)
            if right < WORLD_W-4 and em[rr, right+1] and not pm[rr, right+1]:
                return (Tool.ROAD, right+1, rr)

    # Build vertical roads
    for rc in road_cols:
        if not ib(rc, 0):
            continue
        wire_nearby = False
        for dx in range(-4, 5):
            nc = rc + dx
            if 0 <= nc < WORLD_W and ((wm[:, nc] | pm[:, nc]).any()):
                wire_nearby = True
                break
        if not wire_nearby:
            continue
        col_road = rm[:, rc]
        if not col_road.any():
            for wr in wire_rows_base:
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            if ib(rc, 50) and em[50, rc]:
                return (Tool.ROAD, rc, 50)
        else:
            indices = np.where(col_road)[0]
            top = int(indices[0])
            bot = int(indices[-1])
            if top > 3 and em[top-1, rc] and not pm[top-1, rc]:
                return (Tool.ROAD, rc, top-1)
            if bot < WORLD_H-4 and em[bot+1, rc] and not pm[bot+1, rc]:
                return (Tool.ROAD, rc, bot+1)

    # ---- Phase 4: Zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score by proximity to existing zones (cluster) and power
        min_plant_dist = np.full(len(cxs_arr), 999999.0)
        for px2, py2 in plant_grid[:12]:
            if ib(px2, py2):
                d = np.abs(cxs_arr - px2).astype(float) + np.abs(cys_arr - py2).astype(float)
                min_plant_dist = np.minimum(min_plant_dist, d)

        zone_score = np.zeros(len(cxs_arr))
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist * 0.5 + min_plant_dist * 0.5
            else:
                zone_score = min_plant_dist
        else:
            zone_score = min_plant_dist

        order = np.argsort(zone_score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---- Phase 5: Civic services (scaled aggressively) ----
    if pop > 20:
        # Many fire stations spread across map
        fire_spots = []
        for fy in range(15, 95, 15):
            for fx in range(15, 110, 20):
                fire_spots.append((fx, fy))
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_spots = []
        for py2 in range(20, 90, 20):
            for px2 in range(20, 105, 25):
                police_spots.append((px2, py2))
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_spots = []
        for pky in range(25, 85, 15):
            for pkx in range(25, 100, 20):
                park_spots.append((pkx, pky))
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 400:
        for stx, sty in [
            (44, 32), (76, 32), (44, 68), (76, 68),
            (22, 46), (98, 46), (22, 54), (98, 54),
            (60, 18), (60, 82), (30, 50), (90, 50),
            (12, 20), (108, 20), (12, 80), (108, 80),
        ]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        for apx, apy in [
            (54, 6), (66, 6), (54, 94), (66, 94),
            (7, 36), (113, 36), (7, 64), (113, 64),
            (25, 6), (95, 6), (25, 94), (95, 94),
        ]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        for spx, spy in [
            (6, 50), (114, 50), (60, 3), (60, 97),
            (20, 3), (100, 3), (20, 97), (100, 97),
            (5, 15), (115, 15), (5, 85), (115, 85),
        ]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend wire near existing plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 50)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: extend road near wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 80)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0,1),(0,-1),(1,0),(-1,0),(2,0),(-2,0),(0,2),(0,-2)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire spines and flanking roads."""
    actions = []
    # Three power plants spread across the map
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Wire seeds adjacent to each plant
    for px in [20, 60, 100]:
        for dy in range(-2, 3):
            actions.append((Tool.WIRE, px + 2, 50 + dy))
    # Flanking roads
    for px in [20, 60, 100]:
        wc = px + 2
        for dy in range(-2, 3):
            actions.append((Tool.ROAD, wc - 1, 50 + dy))
            actions.append((Tool.ROAD, wc + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- CLUSTER DEFINITIONS ----
    # 5 main clusters: each has a wire_col, plant_x, center_y
    # Layout spreads across map for full coverage
    clusters = [
        {'cx': 10, 'cy': 25},
        {'cx': 35, 'cy': 25},
        {'cx': 60, 'cy': 50},
        {'cx': 85, 'cy': 75},
        {'cx': 110, 'cy': 75},
        {'cx': 10, 'cy': 75},
        {'cx': 35, 'cy': 75},
        {'cx': 85, 'cy': 25},
        {'cx': 110, 'cy': 25},
    ]

    # Determine how many clusters to activate based on population
    def num_active():
        if pop < 100:
            return 1
        elif pop < 400:
            return 2
        elif pop < 900:
            return 3
        elif pop < 1800:
            return 5
        elif pop < 3500:
            return 7
        else:
            return 9

    n_active = num_active()
    active_clusters = clusters[:n_active]

    # ---- BUILD PROXIMITY MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ENSURE POWER PLANTS for each active cluster ----
    for cl in active_clusters:
        cx, cy = cl['cx'], cl['cy']
        # Check if there's already a plant within 12 tiles
        has_plant = False
        for dy in range(-12, 13):
            for dx in range(-12, 13):
                nx, ny = cx + dx, cy + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant at cx, cy or nearby
            for r in range(0, 10):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- EXTEND WIRE SPINES for active clusters ----
    spine_half = min(45, 12 + pop // 15)
    for cl in active_clusters:
        cx, cy = cl['cx'], cl['cy']
        wc = cx  # wire column at cluster center x
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        target_top = max(2, cy - spine_half)
        target_bot = min(WORLD_H - 3, cy + spine_half)

        if not wire_in_col:
            # Seed wire near a plant
            for dy2 in range(-5, 6):
                ny = cy + dy2
                if ib(wc, ny) and (bool(em[ny, wc]) or bool(wm[ny, wc])) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- EXTEND ROADS flanking wire spines ----
    road_half = min(45, 10 + pop // 20)
    for idx, cl in enumerate(active_clusters):
        cx, cy = cl['cx'], cl['cy']
        wc = cx
        rl, rr = wc - 1, wc + 1
        wire_in_col = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not wire_in_col:
            continue
        target_top = max(2, cy - road_half)
        target_bot = min(WORLD_H - 3, cy + road_half)
        cycle = (step + idx * 3) % 3
        for wr in wire_in_col[cycle::3]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL WIRE CONNECTIONS between clusters ----
    # Connect neighboring clusters horizontally via wire at their cy
    sorted_by_x = sorted(active_clusters, key=lambda c: c['cx'])
    for i in range(len(sorted_by_x) - 1):
        c1 = sorted_by_x[i]
        c2 = sorted_by_x[i + 1]
        # Only connect if reasonably close
        if abs(c2['cx'] - c1['cx']) > 40:
            continue
        conn_y = (c1['cy'] + c2['cy']) // 2
        # Try a few y levels
        for try_y in [conn_y, c1['cy'], c2['cy']]:
            all_connected = True
            for cx_try in range(c1['cx'], c2['cx'] + 1):
                if ib(cx_try, try_y) and not bool(wm[try_y, cx_try]) and not bool(pm[try_y, cx_try]) and not bool(rm[try_y, cx_try]):
                    all_connected = False
                    break
            if not all_connected:
                for cx_try in range(c1['cx'], c2['cx'] + 1):
                    if ib(cx_try, try_y) and bool(em[try_y, cx_try]) and not bool(pm[try_y, cx_try]):
                        return (Tool.WIRE, cx_try, try_y)

    # ---- HORIZONTAL ROAD CONNECTIONS ----
    if pop > 100:
        road_y_levels = [cy for cl in active_clusters for cy in [cl['cy'] - 2, cl['cy'] + 2]]
        road_y_levels = list(set(road_y_levels))
        for conn_y in road_y_levels:
            if conn_y < 2 or conn_y >= WORLD_H - 2:
                continue
            road_in_row = [c for c in range(WORLD_W) if ib(c, conn_y) and bool(rm[conn_y, c])]
            if not road_in_row:
                continue
            min_rc = min(road_in_row)
            max_rc = max(road_in_row)
            # Extend roads between active cluster road columns
            for cl in sorted_by_x:
                rc = cl['cx'] - 1
                if rc < min_rc:
                    for cx_try in range(rc, min_rc):
                        if ib(cx_try, conn_y) and bool(em[conn_y, cx_try]) and not bool(pm[conn_y, cx_try]):
                            return (Tool.ROAD, cx_try, conn_y)
                rc = cl['cx'] + 1
                if rc > max_rc:
                    for cx_try in range(max_rc + 1, rc + 1):
                        if ib(cx_try, conn_y) and bool(em[conn_y, cx_try]) and not bool(pm[conn_y, cx_try]):
                            return (Tool.ROAD, cx_try, conn_y)

    # ---- ZONE PLACEMENT near road + wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by proximity to any active cluster center
        best_dist = np.full(len(cxs_arr), 999999.0)
        for cl in active_clusters:
            d = (np.abs(cxs_arr - cl['cx']).astype(float) +
                 np.abs(cys_arr - cl['cy']).astype(float) * 0.5)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS from existing road near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 100:
        fire_spots = []
        for cl in active_clusters:
            fire_spots.extend([
                (cl['cx'] - 8, cl['cy'] - 8),
                (cl['cx'] + 8, cl['cy'] - 8),
                (cl['cx'] - 8, cl['cy'] + 8),
                (cl['cx'] + 8, cl['cy'] + 8),
            ])
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = []
        for cl in active_clusters:
            police_spots.extend([
                (cl['cx'] - 5, cl['cy']),
                (cl['cx'] + 5, cl['cy']),
            ])
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [(35, 12), (85, 12), (35, 88), (85, 88),
                         (10, 50), (110, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [(30, 15), (90, 15), (30, 85), (90, 85),
                      (60, 20), (60, 80)]
        for nx, ny in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3500:
        for asp in [(60, 8), (5, 50), (115, 50), (60, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 90), (115, 10), (115, 90), (5, 10)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones to boost land value ----
    if pop > 300:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 15)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Multi-neighborhood city policy with 3 power plants and dense grid layout

def init(obs, state):
    """Bootstrap: place 3 coal plants and initial wire connections"""
    actions = []
    # Plant 1: left neighborhood center
    actions.append((Tool.COALPOWER, 25, 50))
    # Wire from plant 1 rightward to seed connectivity
    for x in range(27, 32):
        actions.append((Tool.WIRE, x, 50))
    # Plant 2: center neighborhood
    actions.append((Tool.COALPOWER, 60, 50))
    for x in range(62, 67):
        actions.append((Tool.WIRE, x, 50))
    # Plant 3: right neighborhood
    actions.append((Tool.COALPOWER, 95, 50))
    for x in range(97, 102):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Track state
    if 'phase' not in state:
        state['phase'] = 0
        state['last_pop'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Three neighborhoods: left (x~25), center (x~60), right (x~95)
    # Each has a vertical wire spine and flanking roads
    neighborhoods = [
        {'px': 25, 'py': 50, 'wire_col': 28, 'road_l': 27, 'road_r': 29},
        {'px': 60, 'py': 50, 'wire_col': 63, 'road_l': 62, 'road_r': 64},
        {'px': 95, 'py': 50, 'wire_col': 98, 'road_l': 97, 'road_r': 99},
    ]

    # Also add horizontal spine neighborhoods above and below
    neighborhoods_h = [
        {'px': 25, 'py': 25, 'wire_col': 28, 'road_l': 27, 'road_r': 29},
        {'px': 60, 'py': 25, 'wire_col': 63, 'road_l': 62, 'road_r': 64},
        {'px': 95, 'py': 25, 'wire_col': 98, 'road_l': 97, 'road_r': 99},
        {'px': 25, 'py': 75, 'wire_col': 28, 'road_l': 27, 'road_r': 29},
        {'px': 60, 'py': 75, 'wire_col': 63, 'road_l': 62, 'road_r': 64},
        {'px': 95, 'py': 75, 'wire_col': 98, 'road_l': 97, 'road_r': 99},
    ]

    # Zone ratio picker
    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Ensure power plants exist for all 3 neighborhoods
    plant_ys, plant_xs = np.where(pm)
    plant_count = len(plant_xs) // 9  # approximate (3x3 per plant)

    # Check if each neighborhood has a nearby plant
    for nb in neighborhoods:
        npx, npy = nb['px'], nb['py']
        nearby = any(
            abs(int(plant_xs[i]) - npx) < 8 and abs(int(plant_ys[i]) - npy) < 8
            for i in range(len(plant_xs))
        )
        if not nearby and in_bounds(npx, npy):
            if bool(em[npy, npx]) or bool(pm[npy, npx]):
                return (Tool.COALPOWER, npx, npy)

    # Determine spine extent based on population
    pop_factor = min(20, obs.city_pop // 20)
    spine_half = 10 + pop_factor

    # Build vertical wire spines for all neighborhoods
    all_wire_cols = [nb['wire_col'] for nb in neighborhoods]

    # Process neighborhoods in round-robin
    nb_idx = obs.step % len(neighborhoods)
    nb = neighborhoods[nb_idx]
    wire_col = nb['wire_col']
    py = nb['py']
    road_l = nb['road_l']
    road_r = nb['road_r']
    spine_top = max(3, py - spine_half)
    spine_bot = min(WORLD_H - 4, py + spine_half)

    # Extend vertical wire spine
    wire_in_col = [r for r in range(WORLD_H) if bool(wm[r, wire_col])]
    if not wire_in_col:
        # Seed wire near plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (bool(em[ny, wire_col]) or bool(wm[ny, wire_col])) and not bool(pm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        if max_wr < spine_bot:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > spine_top:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Build road columns flanking wire spine
    if wire_in_col:
        for wr in wire_in_col:
            if in_bounds(road_l, wr) and bool(em[wr, road_l]) and not bool(pm[wr, road_l]):
                return (Tool.ROAD, road_l, wr)
            if in_bounds(road_r, wr) and bool(em[wr, road_r]) and not bool(pm[wr, road_r]):
                return (Tool.ROAD, road_r, wr)

    # Add extra road columns further out when population grows
    if obs.city_pop > 300:
        extra_l = road_l - 4
        extra_r = road_r + 4
        # Connect with horizontal wire at top/bottom
        for wr in wire_in_col:
            if in_bounds(extra_l, wr) and bool(em[wr, extra_l]) and not bool(pm[wr, extra_l]):
                return (Tool.ROAD, extra_l, wr)
            if in_bounds(extra_r, wr) and bool(em[wr, extra_r]) and not bool(pm[wr, extra_r]):
                return (Tool.ROAD, extra_r, wr)
        # Wire bridge from spine to extra road
        for wc in range(road_l - 1, extra_l - 1, -1):
            if in_bounds(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                return (Tool.WIRE, wc, py)
        for wc in range(road_r + 1, extra_r + 2):
            if in_bounds(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                return (Tool.WIRE, wc, py)

    # Connect neighborhoods with horizontal wire/road bridge
    if obs.city_pop > 100:
        # Wire bridge between nb0 and nb1 at row py
        bridge_y = 50
        for x in range(neighborhoods[0]['wire_col'], neighborhoods[1]['wire_col']):
            if in_bounds(x, bridge_y) and bool(em[bridge_y, x]) and not bool(pm[bridge_y, x]):
                return (Tool.WIRE, x, bridge_y)
        # Road bridge just below
        for x in range(neighborhoods[0]['road_r'], neighborhoods[1]['road_l']):
            if in_bounds(x, bridge_y + 2) and bool(em[bridge_y + 2, x]) and not bool(pm[bridge_y + 2, x]):
                return (Tool.ROAD, x, bridge_y + 2)

    if obs.city_pop > 200:
        bridge_y = 50
        for x in range(neighborhoods[1]['wire_col'], neighborhoods[2]['wire_col']):
            if in_bounds(x, bridge_y) and bool(em[bridge_y, x]) and not bool(pm[bridge_y, x]):
                return (Tool.WIRE, x, bridge_y)
        for x in range(neighborhoods[1]['road_r'], neighborhoods[2]['road_l']):
            if in_bounds(x, bridge_y + 2) and bool(em[bridge_y + 2, x]) and not bool(pm[bridge_y + 2, x]):
                return (Tool.ROAD, x, bridge_y + 2)

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Place zones near roads and power
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer candidates near any of the three wire spines
        min_dist = np.full(len(cxs), np.inf)
        for nb2 in neighborhoods:
            d = np.abs(cxs - nb2['wire_col']) + np.abs(cys - nb2['py']) * 0.5
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # Extend roads from existing roads
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 20)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Services at population thresholds
    if obs.city_pop > 200:
        for fpos in [(20, 40), (55, 40), (90, 40), (20, 60), (55, 60), (90, 60)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 500:
        for ppos in [(20, 45), (55, 45), (90, 45), (20, 55), (55, 55), (90, 55)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 1000:
        for spos in [(40, 50), (78, 50)]:
            ssx, ssy = spos
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    # Expand wire laterally as fallback
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plants at 6 columns across the map with wire+road spines."""
    actions = []
    # 6 plants spread across the middle row
    for px in [10, 30, 50, 70, 90, 110]:
        actions.append((Tool.COALPOWER, px, 50))
        # Wire spine vertically around plant
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, 50 + dy))
        # Roads flanking wire
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        # Aim for ~25% industrial, ~30% commercial, ~45% residential
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 columns x 5 rows = 30 anchors across the 120x100 map
    # Column x positions: 10, 30, 50, 70, 90, 110
    # Row y positions: 15, 32, 50, 68, 85
    anchors = []
    for row_y in [15, 32, 50, 68, 85]:
        for col_x in [10, 30, 50, 70, 90, 110]:
            wc = col_x
            rl = col_x - 1
            rr = col_x + 1
            anchors.append((col_x, row_y, wc, rl, rr))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 600:   return 10
        if pop < 1000:  return 14
        if pop < 1800:  return 18
        if pop < 3000:  return 22
        if pop < 5000:  return 26
        return 30

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    # Each group of 5 anchors (one per column) shares a plant at the middle row (row_y=50)
    # Plants placed in init, but check if missing
    plant_cols = [10, 30, 50, 70, 90, 110]
    needed_plants = max(1, min(6, 1 + pop // 200))
    for px in plant_cols[:needed_plants]:
        py = 50
        has_plant = False
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # Nuclear plants when pop grows large
    if pop > 2000:
        nuke_cols = [20, 60, 100]
        for px in nuke_cols:
            py = 10
            has_plant = False
            y0 = max(0, py - 4); y1 = min(WORLD_H, py + 5)
            x0 = max(0, px - 4); x1 = min(WORLD_W, px + 5)
            if np.any(pm[y0:y1, x0:x1]):
                has_plant = True
            if not has_plant:
                if ib(px, py) and bool(em[py, px]):
                    return (Tool.NUCLEARPOWER, px, py)

    # ---- WIRE SPINE BUILDING (vertical) ----
    spine_half = min(20, 5 + pop // 30)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-3, 4):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    if n_active >= 7:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 30:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            # Horizontal roads above and below wire row
            for horiz_y in [yl - 2, yl + 2]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS-STREETS between column groups (every 10 cols) ----
    if pop > 200:
        cross_xs = [5, 20, 40, 60, 80, 100, 115]
        for yl in y_levels:
            for cx in cross_xs:
                for horiz_y in [yl - 4, yl + 4]:
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (dense placement) ----
    # Fire stations: 1 per neighborhood (~every 15 cols, every 15 rows)
    if pop > 80:
        fire_spots = []
        for fy in range(8, 100, 17):
            for fx in range(5, 120, 20):
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = []
        for py2 in range(12, 100, 17):
            for px2 in range(8, 120, 25):
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (25, 5), (65, 5), (105, 5),
            (25, 94), (65, 94), (105, 94),
            (5, 25), (5, 50), (5, 75),
            (115, 25), (115, 50), (115, 75),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        airport_spots = [(55, 6), (5, 50), (115, 50), (55, 94)]
        for (ax, ay) in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        seaport_spots = [(5, 93), (115, 93), (60, 97), (5, 6), (115, 6)]
        for (sx2, sy2) in seaport_spots:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in a 3x3 grid covering the map."""
    actions = []
    # 3x3 grid of plants at roughly equal spacing
    plant_positions = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine from plant
        for dy in range(-3, 4):
            ny = py + dy
            if 0 <= ny < 100:
                actions.append((Tool.WIRE, px, ny))
        # Horizontal wire from plant
        for dx in range(-3, 4):
            nx = px + dx
            if 0 <= nx < 120:
                actions.append((Tool.WIRE, nx, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 40% res, 35% com, 25% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9-cluster layout: 3x3 grid
    all_clusters = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 3
        if pop < 300:  return 5
        if pop < 600:  return 7
        if pop < 1000: return 8
        return 9

    n_active = num_active()
    active_centers = all_clusters[:n_active]

    # --- ENSURE POWER PLANTS ---
    for (px, py) in active_centers:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find nearest empty spot
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE GRID: both horizontal and vertical spines per cluster ---
    spine_half = min(20, 6 + pop // 20)
    for (px, py) in active_centers:
        # Vertical spine
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for wy in range(spine_top, spine_bot + 1):
            if ib(px, wy) and not bool(pm[wy, px]) and not bool(wm[wy, px]):
                if bool(em[wy, px]):
                    return (Tool.WIRE, px, wy)
        # Horizontal spine
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        for wx in range(spine_left, spine_right + 1):
            if ib(wx, py) and not bool(pm[py, wx]) and not bool(wm[py, wx]):
                if bool(em[py, wx]):
                    return (Tool.WIRE, wx, py)

    # --- HORIZONTAL WIRE connecting clusters in same row ---
    row_ys = sorted(set(py for (px, py) in active_centers))
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl], key=lambda a: a[0])
        for i in range(len(row_cs) - 1):
            x1c = row_cs[i][0]
            x2c = row_cs[i + 1][0]
            for cx in range(x1c + 1, x2c):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting clusters in same column ---
    col_xs = sorted(set(px for (px, py) in active_centers))
    for xc in col_xs:
        col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc], key=lambda a: a[1])
        for i in range(len(col_cs) - 1):
            y1c = col_cs[i][1]
            y2c = col_cs[i + 1][1]
            for cy in range(y1c + 1, y2c):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # --- ROADS: grid roads flanking wire spines ---
    # Horizontal roads at offsets from cluster centers
    road_offsets = [-4, -3, 3, 4]
    for (px, py) in active_centers:
        for dy_off in road_offsets:
            ry = py + dy_off
            if not ib(px, ry):
                continue
            # Road runs horizontally across cluster width
            for dx in range(-spine_half, spine_half + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Vertical roads at offsets from cluster centers
    v_road_offsets = [-4, -3, 3, 4]
    for (px, py) in active_centers:
        for dx_off in v_road_offsets:
            rx = px + dx_off
            if not ib(rx, py):
                continue
            for dy in range(-spine_half, spine_half + 1):
                ry = py + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # --- INTER-CLUSTER ROADS (horizontal) ---
    if pop > 50:
        for yl in row_ys:
            row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl], key=lambda a: a[0])
            if len(row_cs) < 2:
                continue
            for road_y in [yl - 4, yl + 4]:
                if not (0 <= road_y < WORLD_H):
                    continue
                x_left = row_cs[0][0] - spine_half
                x_right = row_cs[-1][0] + spine_half
                for cx in range(max(0, x_left), min(WORLD_W, x_right + 1)):
                    if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                        return (Tool.ROAD, cx, road_y)

    # --- INTER-CLUSTER ROADS (vertical) ---
    if pop > 100:
        for xc in col_xs:
            col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc], key=lambda a: a[1])
            if len(col_cs) < 2:
                continue
            for road_x in [xc - 4, xc + 4]:
                if not (0 <= road_x < WORLD_W):
                    continue
                y_top = col_cs[0][1] - spine_half
                y_bot = col_cs[-1][1] + spine_half
                for cy in range(max(0, y_top), min(WORLD_H, y_bot + 1)):
                    if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                        return (Tool.ROAD, road_x, cy)

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_centers:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES ---
    if pop > 60:
        fire_spots = [
            (8, 10), (35, 10), (65, 10), (95, 10), (112, 10),
            (8, 35), (35, 35), (65, 35), (95, 35), (112, 35),
            (8, 65), (35, 65), (65, 65), (95, 65), (112, 65),
            (8, 90), (35, 90), (65, 90), (95, 90), (112, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (12, 20), (42, 20), (72, 20), (102, 20),
            (12, 50), (42, 50), (72, 50), (102, 50),
            (12, 80), (42, 80), (72, 80), (102, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (30, 5), (70, 5), (110, 5),
            (30, 95), (70, 95), (110, 95),
            (5, 30), (5, 70),
            (115, 30), (115, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power for extra capacity
    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (40, 5), (80, 5), (40, 95), (80, 95),
            (5, 40), (5, 60), (115, 40), (115, 60),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS to boost land value ---
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- FALLBACK: extend wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
